INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES
('fd0ff1dd-4856-4f51-b2a8-d914ed6a4d19', '051b209e-9985-44da-a832-ca884783cb98', 1, 'A Vontade Adormecida', NULL, '{"intro": "Psicologicamente, a vontade fraca \u00e9 fruto de decis\u00f5es adiadas.", "prayer": "Identifique uma \u00e1rea de pregui\u00e7a e a enfrente.", "practice": "Tome uma pequena decis\u00e3o hoje e cumpra-a imediatamente.", "reflection": "O maior inimigo da virtude n\u00e3o \u00e9 o erro, \u00e9 a in\u00e9rcia.", "journal_prompt": "O que voc\u00ea est\u00e1 evitando decidir?"}'),
('d6c3dab7-7d22-4195-92f3-472f6de6bc16', '051b209e-9985-44da-a832-ca884783cb98', 2, 'O Ordenamento dos Afetos', NULL, '{"intro": "Desordem emocional gera ansiedade constante.", "prayer": "Ore pedindo a gra\u00e7a de amar o que \u00e9 eterno.", "practice": "Escolha um objeto em sua casa e o organize conscientemente.", "reflection": "Amar \u00e9 colocar as coisas no seu devido lugar.", "journal_prompt": "Seus amores est\u00e3o em ordem?"}'),
('f9ed5e91-2888-4f7e-8499-85f71ffe2101', '051b209e-9985-44da-a832-ca884783cb98', 3, 'A Força do Hábito', NULL, '{"intro": "H\u00e1bitos s\u00e3o os trilhos sobre os quais nossa vida corre.", "prayer": "Pe\u00e7a const\u00e2ncia para as pequenas coisas.", "practice": "Inicie hoje um novo micro-h\u00e1bito positivo.", "reflection": "Somos o que fazemos repetidamente.", "journal_prompt": "Quais trilhos voc\u00ea est\u00e1 construindo hoje?"}'),
('8c2ff870-c484-4716-b31b-cf4d3ed019e5', '051b209e-9985-44da-a832-ca884783cb98', 4, 'O Silêncio Educativo', NULL, '{"intro": "Falar demais \u00e9 uma fuga do encontro consigo mesmo.", "prayer": "No sil\u00eancio, escute os batimentos do seu cora\u00e7\u00e3o.", "practice": "Fique 30 minutos sem falar nada, apenas observando.", "reflection": "Quem n\u00e3o domina a pr\u00f3pria l\u00edngua n\u00e3o domina a si mesmo.", "journal_prompt": "O que o seu barulho tenta esconder?"}'),
('5faa51eb-e635-4b43-bd47-627c5fa2efcf', '051b209e-9985-44da-a832-ca884783cb98', 5, 'A Obediência à Verdade', NULL, '{"intro": "Negar a realidade \u00e9 a raiz de todo sofrimento ps\u00edquico.", "prayer": "Abrace a sua fragilidade diante do Infinito.", "practice": "Aceite uma verdade dif\u00edcil sobre voc\u00ea hoje.", "reflection": "A liberdade real nasce de submeter-se ao que \u00e9 verdadeiro.", "journal_prompt": "Voc\u00ea prefere a mentira que conforta ou a verdade que cura?"}'),
('93c7e138-b527-4d3d-962e-df7b7447184a', '051b209e-9985-44da-a832-ca884783cb98', 6, 'A Coragem do Não', NULL, '{"intro": "A incapacidade de dizer n\u00e3o \u00e9 falta de identidade.", "prayer": "Pe\u00e7a for\u00e7a para sustentar suas escolhas.", "practice": "Diga n\u00e3o a algo que rouba o seu tempo hoje.", "reflection": "Dizer sim a tudo \u00e9 dizer n\u00e3o a si mesmo.", "journal_prompt": "A quem voc\u00ea est\u00e1 tentando agradar?"}'),
('7c57cc31-4852-4427-b2d7-02a25e3de1a5', '051b209e-9985-44da-a832-ca884783cb98', 7, 'O Caráter que se Ergue', NULL, '{"intro": "O homem formado \u00e9 aquele que se torna porto seguro para os outros.", "prayer": "Agrade\u00e7a pela jornada de fortalecimento.", "practice": "Fa\u00e7a algo por algu\u00e9m sem esperar nada em troca.", "reflection": "A forma\u00e7\u00e3o termina quando a sua vida se torna um dom.", "journal_prompt": "Quem pode contar com voc\u00ea hoje?"}'),
('182be334-906b-447c-8bb7-7be26c2ed328', '0b8ddab7-b106-4873-bc4d-3987421d265d', 1, 'O Despertar Sagrado', NULL, '{"intro": "O primeiro pensamento do dia \u00e9 a semente de todas as suas a\u00e7\u00f5es.", "prayer": "Ofere\u00e7a o seu dia antes de sair da cama.", "practice": "N\u00e3o pegue no celular nos primeiros 15 minutos do dia.", "reflection": "A forma como voc\u00ea come\u00e7a o dia determina a sua alma.", "journal_prompt": "Qual \u00e9 a primeira coisa que voc\u00ea entrega ao mundo ao acordar?"}'),
('57763fc6-f48e-436d-a54f-f3431216a562', '0b8ddab7-b106-4873-bc4d-3987421d265d', 2, 'O Dever do Momento', NULL, '{"intro": "A ansiedade nasce de querer estar no futuro e negligenciar o presente.", "prayer": "Pe\u00e7a a gra\u00e7a da presen\u00e7a de esp\u00edrito.", "practice": "Fa\u00e7a a sua tarefa mais chata com total aten\u00e7\u00e3o e amor.", "reflection": "A santidade est\u00e1 em fazer bem o que se deve fazer agora.", "journal_prompt": "Voc\u00ea est\u00e1 presente no que est\u00e1 fazendo?"}'),
('99ec6d50-4d70-4e62-9da8-e7ddcc40d68d', '0b8ddab7-b106-4873-bc4d-3987421d265d', 3, 'As Pequenas Mortes', NULL, '{"intro": "Pequenos sacrif\u00edcios fortalecem a alma contra grandes quedas.", "prayer": "Ofere\u00e7a essa pequena morte pela convers\u00e3o de algu\u00e9m.", "practice": "Renuncie a uma pequena satisfa\u00e7\u00e3o hoje (um caf\u00e9, um doce, um coment\u00e1rio).", "reflection": "Cada ren\u00fancia \u00e9 um espa\u00e7o que se abre para a vida.", "journal_prompt": "O que voc\u00ea pode soltar para ser mais livre?"}'),
('690f82c8-60c1-4876-81ea-db828cbb8172', '0b8ddab7-b106-4873-bc4d-3987421d265d', 4, 'A Alimentação da Alma', NULL, '{"intro": "O que voc\u00ea l\u00ea, assiste e ouve molda a sua percep\u00e7\u00e3o da realidade.", "prayer": "Pe\u00e7a discernimento para o que voc\u00ea deixa entrar pelos olhos.", "practice": "Leia 5 p\u00e1ginas de um livro espiritual em vez de rolar as redes sociais.", "reflection": "Voc\u00ea se torna o que voc\u00ea consome.", "journal_prompt": "Como est\u00e1 a sa\u00fade da sua alma hoje?"}'),
('995d2b5f-1b4c-4a45-a32b-4454c650afc2', '0b8ddab7-b106-4873-bc4d-3987421d265d', 5, 'O Encontro no Meio do Dia', NULL, '{"intro": "A rotina nos engole se n\u00e3o criarmos ilhas de sil\u00eancio.", "prayer": "Recite o Angelus ou uma ora\u00e7\u00e3o curta de entrega.", "practice": "Pare tudo por 2 minutos ao meio-dia para uma ora\u00e7\u00e3o r\u00e1pida.", "reflection": "Uma pausa para respirar \u00e9 uma pausa para lembrar de Deus.", "journal_prompt": "Voc\u00ea se lembrou dEle hoje?"}'),
('49208096-da61-4368-9311-7f68034f6a7e', '0b8ddab7-b106-4873-bc4d-3987421d265d', 6, 'A Caridade Ordinária', NULL, '{"intro": "O amor se prova na paci\u00eancia com quem est\u00e1 ao nosso lado.", "prayer": "Pe\u00e7a para ver Cristo no pr\u00f3ximo.", "practice": "Fa\u00e7a um elogio sincero a algu\u00e9m que convive com voc\u00ea.", "reflection": "N\u00e3o espere grandes ocasi\u00f5es para amar.", "journal_prompt": "Quem voc\u00ea amou hoje de forma concreta?"}'),
('d71cbf89-8f87-414f-8eeb-675a3959172a', '0b8ddab7-b106-4873-bc4d-3987421d265d', 7, 'O Exame da Noite', NULL, '{"intro": "O fim do dia \u00e9 o tempo da colheita e do perd\u00e3o.", "prayer": "Pe\u00e7a perd\u00e3o pelas falhas e agrade\u00e7a pelas vit\u00f3rias.", "practice": "Reveja o seu dia antes de dormir: onde houve amor? Onde faltou?", "reflection": "Ningu\u00e9m melhora o que n\u00e3o avalia.", "journal_prompt": "Se hoje fosse o seu \u00faltimo dia, voc\u00ea estaria em paz?"}'),
('12bea220-594b-4e61-952f-98f4fdca8436', '150f78d3-019b-40c0-962e-a83576309ea5', 1, 'O Centro de Gravidade', NULL, '{"intro": "O cora\u00e7\u00e3o \u00e9 o centro de comando de todas as nossas decis\u00f5es.", "prayer": "Pe\u00e7a para ancorar seu cora\u00e7\u00e3o na Verdade.", "practice": "Observe para onde o seu pensamento foge quando voc\u00ea est\u00e1 livre.", "reflection": "Onde est\u00e1 o teu tesouro, a\u00ed estar\u00e1 o teu cora\u00e7\u00e3o.", "journal_prompt": "O que ocupa o trono do seu cora\u00e7\u00e3o hoje?"}'),
('62d23419-0510-4f35-9098-8111d5a7a3c8', '150f78d3-019b-40c0-962e-a83576309ea5', 2, 'A Ferida Aberta', NULL, '{"intro": "A vulnerabilidade \u00e9 a porta de entrada para a gra\u00e7a.", "prayer": "Mostre a Ele o seu cora\u00e7\u00e3o partido.", "practice": "N\u00e3o esconda a sua tristeza hoje; sinta-a diante dEle.", "reflection": "\u00c9 pela rachadura no cora\u00e7\u00e3o que a luz entra.", "journal_prompt": "O que voc\u00ea est\u00e1 tentando proteger com tanto esfor\u00e7o?"}'),
('707485e8-6dc0-4b5e-9dc4-f69cf221bcf0', '150f78d3-019b-40c0-962e-a83576309ea5', 3, 'A Pureza da Intenção', NULL, '{"intro": "Muitas vezes fazemos coisas boas por motivos ego\u00edstas.", "prayer": "Pe\u00e7a um cora\u00e7\u00e3o puro e reto.", "practice": "Escolha uma tarefa e a realize com a inten\u00e7\u00e3o de agradar a Deus.", "reflection": "Faze o que fazes, por amor e s\u00f3 por amor.", "journal_prompt": "Por que voc\u00ea faz o que faz?"}'),
('b8cf5df7-c0a4-43ad-b4f3-6e93e7a839a2', '150f78d3-019b-40c0-962e-a83576309ea5', 4, 'O Coração que Escuta', NULL, '{"intro": "Escutar \u00e9 a forma mais profunda de amar.", "prayer": "Escute o sil\u00eancio de Deus no seu peito.", "practice": "Escute algu\u00e9m hoje sem interromper, sem julgar.", "reflection": "O amor tem ouvidos que a raz\u00e3o desconhece.", "journal_prompt": "Voc\u00ea est\u00e1 realmente ouvindo ou apenas esperando sua vez de falar?"}'),
('f19f7093-d270-46d1-9ce8-7a088991e5d3', '150f78d3-019b-40c0-962e-a83576309ea5', 5, 'A Fortaleza Mansa', NULL, '{"intro": "A mansid\u00e3o \u00e9 o dom\u00ednio total das pr\u00f3prias paix\u00f5es.", "prayer": "Pe\u00e7a um cora\u00e7\u00e3o manso e humilde.", "practice": "Responda com do\u00e7ura a uma provoca\u00e7\u00e3o hoje.", "reflection": "A verdadeira for\u00e7a n\u00e3o \u00e9 a que grita, \u00e9 a que sustenta.", "journal_prompt": "A sua for\u00e7a vem do medo ou da paz?"}'),
('16373f39-c20d-4ca5-97e1-f294dcc349d4', '150f78d3-019b-40c0-962e-a83576309ea5', 6, 'A Alegria Profunda', NULL, '{"intro": "A alegria crist\u00e3 \u00e9 uma decis\u00e3o, n\u00e3o um sentimento passageiro.", "prayer": "Agrade\u00e7a por 5 pequenas alegrias do dia.", "practice": "Sorria para tr\u00eas estranhos hoje.", "reflection": "Um cora\u00e7\u00e3o triste \u00e9 um alvo f\u00e1cil para o mal.", "journal_prompt": "Onde voc\u00ea busca a sua alegria?"}'),
('bb058649-ab7c-4216-9203-7cb95d316bc4', '150f78d3-019b-40c0-962e-a83576309ea5', 7, 'A Morada do Amado', NULL, '{"intro": "Toda busca humana \u00e9, no fundo, uma busca pelo Lar.", "prayer": "Descanse na presen\u00e7a dEle dentro de voc\u00ea.", "practice": "Sinta o seu cora\u00e7\u00e3o como um templo sagrado.", "reflection": "O cora\u00e7\u00e3o \u00e9 um abismo que s\u00f3 o Infinito pode preencher.", "journal_prompt": "Voc\u00ea j\u00e1 se sentiu em casa?"}'),
('39102329-9633-4eea-8b4e-3e3da8ec8815', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 1, 'A Rocha e a Areia', NULL, '{"intro": "Fundamentos invis\u00edveis sustentam estruturas vis\u00edveis.", "prayer": "Pe\u00e7a para construir sua vida sobre o que \u00e9 eterno.", "practice": "Analise em que base sua seguran\u00e7a hoje se apoia.", "reflection": "Onde voc\u00ea est\u00e1 construindo a sua casa?", "journal_prompt": "Se tudo desabasse, o que sobraria de voc\u00ea?"}'),
('8399a510-c51a-426e-ac6a-386a50ce893e', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 2, 'A Revelação do Sentido', NULL, '{"intro": "A busca por sentido \u00e9 a necessidade mais profunda da alma.", "prayer": "Contemple a cria\u00e7\u00e3o e veja nela um recado para voc\u00ea.", "practice": "Observe a beleza de algo simples ao seu redor.", "reflection": "A vida n\u00e3o \u00e9 um acaso, \u00e9 um chamado.", "journal_prompt": "O que a vida est\u00e1 pedindo de voc\u00ea agora?"}'),
('455223dc-ebfb-4b93-99f2-c5835037f4e4', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 3, 'O Mistério da Encarnação', NULL, '{"intro": "A realidade material \u00e9 sagrada e cheia de presen\u00e7a.", "prayer": "Agrade\u00e7a pela sua humanidade limitada.", "practice": "Toque a terra, sinta o seu corpo, habite o presente.", "reflection": "Deus se fez carne para que a carne se tornasse divina.", "journal_prompt": "Voc\u00ea aceita as limita\u00e7\u00f5es da sua pr\u00f3pria carne?"}'),
('6ed33434-274a-4020-bca3-3a10bf234d08', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 4, 'A Lei do Amor', NULL, '{"intro": "A lei sem amor \u00e9 escravid\u00e3o; o amor sem lei \u00e9 caos.", "prayer": "Pe\u00e7a para ver o outro como Ele o v\u00ea.", "practice": "Aja hoje motivado apenas pelo amor, n\u00e3o pelo dever.", "reflection": "N\u00e3o existem regras, existe uma Pessoa a quem amamos.", "journal_prompt": "O que move as suas a\u00e7\u00f5es: o medo ou o amor?"}'),
('859fc2d1-0d9f-4e12-a9ab-6f16e22a36a1', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 5, 'A Comunhão dos Santos', NULL, '{"intro": "A solid\u00e3o \u00e9 um mito; estamos todos interconectados.", "prayer": "Sinta a companhia daqueles que j\u00e1 venceram.", "practice": "Lembre-se de algu\u00e9m que te inspira e siga seu exemplo.", "reflection": "Ningu\u00e9m caminha sozinho para o alto.", "journal_prompt": "Quem caminha com voc\u00ea no seu cora\u00e7\u00e3o?"}'),
('e9f5a167-6858-4495-b2b1-c9c96c462582', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 6, 'A Cruz como Portal', NULL, '{"intro": "A aceita\u00e7\u00e3o da dor \u00e9 a chave para a verdadeira paz.", "prayer": "Ofere\u00e7a sua dor como um gesto de amor.", "practice": "N\u00e3o reclame de um pequeno desconforto hoje.", "reflection": "O sofrimento n\u00e3o \u00e9 um beco sem sa\u00edda, \u00e9 uma passagem.", "journal_prompt": "O que voc\u00ea est\u00e1 tentando evitar a qualquer custo?"}'),
('9812a6fd-f7c5-4b3b-b44e-97aa508d327e', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 7, 'A Esperança da Glória', NULL, '{"intro": "A esperan\u00e7a nos permite viver o futuro no presente.", "prayer": "Descanse na promessa de que tudo ficar\u00e1 bem.", "practice": "Olhe para o horizonte e sorria para o amanh\u00e3.", "reflection": "O fim da jornada \u00e9 apenas o verdadeiro come\u00e7o.", "journal_prompt": "Pelo que voc\u00ea est\u00e1 esperando?"}'),
('998b1157-ad77-4a35-a53b-7b6cb6fa67fc', 'a1a1a1a1-3030-4000-8000-000000000001', 1, 'Dia 1 — Inquietação', 'Semana 1: Despertar', '{"pch": "Antes de te formar no ventre\u2026 Eu j\u00e1 te conhecia. Voc\u00ea n\u00e3o \u00e9 acidente \u2014 \u00e9 projeto.", "verse": "Jr 1,5", "lectio": "Leia Jr 1,4-10 lentamente. Perceba que Deus fala antes de voc\u00ea agir.", "practice": "Escreva 3 coisas que te fazem sentir vivo.", "question": "O que te inquieta quando pensa no futuro?"}'),
('4c0d4e4c-d023-49e8-9015-bab9638bd850', 'a1a1a1a1-3030-4000-8000-000000000001', 2, 'Dia 2 — Escuta', 'Semana 1: Despertar', '{"pch": "Fala, Senhor\u2026 seu servo escuta. E se a voz que voc\u00ea ignora fosse a mais importante?", "verse": "1Sm 3,10", "lectio": "Leia 1Sm 3,1-10. Samuel precisou aprender a reconhecer a voz.", "practice": "Fique 5 minutos em sil\u00eancio absoluto. Anote o que surgir.", "question": "Quando foi a \u00faltima vez que voc\u00ea parou para ouvir?"}'),
('5138f2ed-b82a-4c75-a2e9-c5c674905476', 'a1a1a1a1-3030-4000-8000-000000000001', 3, 'Dia 3 — Identidade', 'Semana 1: Despertar', '{"pch": "Voc\u00ea foi tecido em segredo\u2026 mas n\u00e3o por acaso. Cada detalhe seu \u00e9 intencional.", "verse": "Sl 139,13-14", "lectio": "Leia Sl 139,13-18. Deus te conhece por dentro.", "practice": "Liste 3 qualidades suas que outros j\u00e1 elogiaram.", "question": "O que voc\u00ea gosta em si mesmo que nunca valorizou?"}'),
('c8b91851-b773-4634-b175-606f16a1bdd4', 'a1a1a1a1-3030-4000-8000-000000000001', 4, 'Dia 4 — Dons', 'Semana 1: Despertar', '{"pch": "A cada um \u00e9 dada uma manifesta\u00e7\u00e3o do Esp\u00edrito\u2026 para o bem de todos. Seus dons n\u00e3o s\u00e3o para voc\u00ea.", "verse": "1Cor 12,7", "lectio": "Leia 1Cor 12,4-11. Cada dom \u00e9 \u00fanico e necess\u00e1rio.", "practice": "Pergunte a 2 pessoas pr\u00f3ximas: qual meu maior talento?", "question": "O que voc\u00ea faz com facilidade que outros acham dif\u00edcil?"}'),
('68da5888-cdf5-4fff-a61b-c6564471e6b6', 'a1a1a1a1-3030-4000-8000-000000000001', 5, 'Dia 5 — Sonhos', 'Semana 1: Despertar', '{"pch": "Ele pode fazer infinitamente mais\u2026 do que pedimos ou imaginamos. Seus sonhos s\u00e3o pequenos demais.", "verse": "Ef 3,20", "lectio": "Leia Ef 3,14-21. A ora\u00e7\u00e3o de Paulo \u00e9 um convite \u00e0 grandeza.", "practice": "Escreva seu maior sonho sem censura.", "question": "Se n\u00e3o houvesse limites, o que voc\u00ea faria?"}'),
('2c6ea5f0-16c1-4157-9983-0e671662dc7d', 'a1a1a1a1-3030-4000-8000-000000000001', 6, 'Dia 6 — Medo', 'Semana 1: Despertar', '{"pch": "N\u00e3o temas, pois estou contigo\u2026 O medo \u00e9 real, mas n\u00e3o \u00e9 verdadeiro.", "verse": "Is 41,10", "lectio": "Leia Is 41,8-13. Deus segura sua m\u00e3o direita.", "practice": "Nomeie seu maior medo. Depois, entregue-o em ora\u00e7\u00e3o.", "question": "Qual medo te impede de avan\u00e7ar?"}'),
('4fe490ab-b93c-4111-903e-f6594093c2ec', 'a1a1a1a1-3030-4000-8000-000000000001', 7, 'Dia 7 — Entrega', 'Semana 1: Despertar', '{"pch": "Confia ao Senhor as tuas obras\u2026 e os teus planos ser\u00e3o estabelecidos. Solte o controle.", "verse": "Pv 16,3", "lectio": "Leia Pv 16,1-9. O cora\u00e7\u00e3o planeja, mas Deus dirige.", "practice": "Fa\u00e7a uma ora\u00e7\u00e3o de entrega: Senhor, minha vida \u00e9 tua.", "question": "O que voc\u00ea precisa entregar a Deus hoje?"}'),
('bb057ba9-b3be-4549-b096-7d10af160978', 'a1a1a1a1-3030-4000-8000-000000000001', 8, 'Dia 8 — Raízes', 'Semana 2: Desconstruir', '{"pch": "Toda \u00e1rvore boa d\u00e1 bons frutos\u2026 Antes de mudar os frutos, examine as ra\u00edzes.", "verse": "Mt 7,17", "lectio": "Leia Mt 7,15-20. Os frutos revelam a raiz.", "practice": "Escreva 3 cren\u00e7as negativas que carrega desde a inf\u00e2ncia.", "question": "Que cren\u00e7as sobre voc\u00ea mesmo te limitam?"}'),
('d43f46b7-ab47-4b02-9524-be185e2f09b4', 'a1a1a1a1-3030-4000-8000-000000000001', 9, 'Dia 9 — Comparação', 'Semana 2: Desconstruir', '{"pch": "Cada um examine a pr\u00f3pria obra\u2026 sem se comparar. Sua corrida \u00e9 s\u00f3 sua.", "verse": "Gl 6,4", "lectio": "Leia Gl 6,1-5. Cada um carregar\u00e1 seu pr\u00f3prio fardo.", "practice": "Desative as redes sociais por 24h. Observe como se sente.", "question": "Com quem voc\u00ea se compara? E por qu\u00ea?"}'),
('5d957e20-f7a8-4aac-b2ce-962d35426dba', 'a1a1a1a1-3030-4000-8000-000000000001', 10, 'Dia 10 — Expectativas', 'Semana 2: Desconstruir', '{"pch": "N\u00e3o se conformem\u2026 Transformem-se. As expectativas dos outros n\u00e3o s\u00e3o o plano de Deus para voc\u00ea.", "verse": "Rm 12,2", "lectio": "Leia Rm 12,1-8. Renovar a mente \u00e9 o caminho.", "practice": "Escreva: o que EU quero vs. o que ESPERAM de mim.", "question": "Que expectativa alheia voc\u00ea carrega como sua?"}'),
('d805edc0-7835-436f-8dca-41e06e9b3b45', 'a1a1a1a1-3030-4000-8000-000000000001', 11, 'Dia 11 — Feridas', 'Semana 2: Desconstruir', '{"pch": "Minha gra\u00e7a te basta\u2026 A for\u00e7a se aperfei\u00e7oa na fraqueza. Suas feridas t\u00eam prop\u00f3sito.", "verse": "2Cor 12,9", "lectio": "Leia 2Cor 12,7-10. Paulo encontrou for\u00e7a na fraqueza.", "practice": "Escreva uma carta de perd\u00e3o a si mesmo.", "question": "Que dor do passado ainda influencia suas decis\u00f5es?"}'),
('eb92ec35-11e0-4f15-adeb-e8b806751a75', 'a1a1a1a1-3030-4000-8000-000000000001', 12, 'Dia 12 — Desapego', 'Semana 2: Desconstruir', '{"pch": "Esquecendo-me do que fica para tr\u00e1s\u2026 avan\u00e7ando para o que est\u00e1 adiante. Solte o passado.", "verse": "Fl 3,13", "lectio": "Leia Fl 3,12-16. Paulo corria para frente.", "practice": "Escolha algo simb\u00f3lico para soltar hoje \u2014 um objeto, uma mem\u00f3ria, um ressentimento.", "question": "O que do passado voc\u00ea precisa largar para avan\u00e7ar?"}'),
('b5e69546-2d9f-4b03-9a62-224c77defd11', 'a1a1a1a1-3030-4000-8000-000000000001', 13, 'Dia 13 — Perdão', 'Semana 2: Desconstruir', '{"pch": "Perdoem como o Senhor perdoou voc\u00eas\u2026 O perd\u00e3o n\u00e3o \u00e9 sentimento \u2014 \u00e9 decis\u00e3o.", "verse": "Cl 3,13", "lectio": "Leia Cl 3,12-17. Revestir-se de compaix\u00e3o.", "practice": "Escreva o nome de quem precisa perdoar. Reze por essa pessoa.", "question": "Quem voc\u00ea ainda n\u00e3o perdoou?"}'),
('a33cfda2-79e6-40b2-b690-0c22e1890abb', 'a1a1a1a1-3030-4000-8000-000000000001', 14, 'Dia 14 — Silêncio', 'Semana 2: Desconstruir', '{"pch": "Aquietai-vos e sabei que Eu sou Deus\u2026 No barulho, voc\u00ea se perde. No sil\u00eancio, se encontra.", "verse": "Sl 46,10", "lectio": "Leia Sl 46. Deus \u00e9 ref\u00fagio no meio do caos.", "practice": "10 minutos de sil\u00eancio contemplativo antes de dormir.", "question": "O que o barulho da sua rotina esconde?"}'),
('3c7aeb85-1858-467c-975d-a666e9d8ebd0', 'a1a1a1a1-3030-4000-8000-000000000001', 15, 'Dia 15 — Visão', 'Semana 3: Reconstruir', '{"pch": "Escreve a vis\u00e3o\u2026 e torna-a clara. O que n\u00e3o est\u00e1 escrito, n\u00e3o se realiza.", "verse": "Hc 2,2", "lectio": "Leia Hc 2,1-4. A vis\u00e3o tem tempo certo.", "practice": "Escreva sua vis\u00e3o de vida em 1 par\u00e1grafo.", "question": "Qual sua vis\u00e3o para os pr\u00f3ximos 5 anos?"}'),
('12e661ac-582e-4c7b-8899-2ac42118bf80', 'a1a1a1a1-3030-4000-8000-000000000001', 16, 'Dia 16 — Valores', 'Semana 3: Reconstruir', '{"pch": "Onde est\u00e1 o teu tesouro\u2026 a\u00ed est\u00e1 o teu cora\u00e7\u00e3o. O que voc\u00ea valoriza define quem voc\u00ea \u00e9.", "verse": "Mt 6,21", "lectio": "Leia Mt 6,19-24. Tesouro no c\u00e9u vs. tesouro na terra.", "practice": "Liste seus 5 valores mais importantes. Veja se sua vida reflete isso.", "question": "Quais s\u00e3o seus 3 valores inegoci\u00e1veis?"}'),
('2e987379-972e-47a4-bcb1-a2ecad2d45c5', 'a1a1a1a1-3030-4000-8000-000000000001', 17, 'Dia 17 — Decisão', 'Semana 3: Reconstruir', '{"pch": "Escolhei hoje a quem servireis\u2026 A indecis\u00e3o tamb\u00e9m \u00e9 uma escolha.", "verse": "Js 24,15", "lectio": "Leia Js 24,14-18. Josu\u00e9 decidiu por toda sua casa.", "practice": "Tome uma decis\u00e3o que est\u00e1 pendente. Qualquer uma. Agora.", "question": "Que decis\u00e3o voc\u00ea est\u00e1 adiando?"}'),
('7c61db8f-303e-4621-83e3-09bac050ac36', 'a1a1a1a1-3030-4000-8000-000000000001', 18, 'Dia 18 — Disciplina', 'Semana 3: Reconstruir', '{"pch": "Disciplino o meu corpo\u2026 Sem disciplina, o prop\u00f3sito vira apenas desejo.", "verse": "1Cor 9,27", "lectio": "Leia 1Cor 9,24-27. Paulo corria para vencer.", "practice": "Escolha 1 h\u00e1bito pequeno e pratique por 7 dias consecutivos.", "question": "Em que \u00e1rea da sua vida falta disciplina?"}'),
('b1976d29-1635-4597-a295-21fb26c1cdcb', 'a1a1a1a1-3030-4000-8000-000000000001', 19, 'Dia 19 — Coragem', 'Semana 3: Reconstruir', '{"pch": "S\u00ea forte e corajoso\u2026 porque o Senhor est\u00e1 contigo. Coragem n\u00e3o \u00e9 aus\u00eancia de medo.", "verse": "Js 1,9", "lectio": "Leia Js 1,1-9. Deus repetiu: s\u00ea forte.", "practice": "Fa\u00e7a uma coisa que te assusta hoje \u2014 mesmo pequena.", "question": "O que voc\u00ea faria se n\u00e3o tivesse medo?"}'),
('bb65465d-4947-48f6-9d6c-a18dbca31406', 'a1a1a1a1-3030-4000-8000-000000000001', 20, 'Dia 20 — Serviço', 'Semana 3: Reconstruir', '{"pch": "O Filho do Homem veio para servir\u2026 Prop\u00f3sito n\u00e3o \u00e9 sobre voc\u00ea \u2014 \u00e9 sobre quem voc\u00ea serve.", "verse": "Mc 10,45", "lectio": "Leia Mc 10,42-45. A lideran\u00e7a \u00e9 servi\u00e7o.", "practice": "Fa\u00e7a algo por algu\u00e9m hoje sem esperar nada em troca.", "question": "Quem se beneficia quando voc\u00ea vive seu melhor?"}'),
('282a548d-3009-4cf5-aa5d-0f01aa82aac2', 'a1a1a1a1-3030-4000-8000-000000000001', 21, 'Dia 21 — Identidade em Cristo', 'Semana 3: Reconstruir', '{"pch": "Se algu\u00e9m est\u00e1 em Cristo\u2026 \u00e9 nova criatura. Sua identidade n\u00e3o est\u00e1 no que voc\u00ea faz, mas em quem voc\u00ea \u00e9.", "verse": "2Cor 5,17", "lectio": "Leia 2Cor 5,14-21. Embaixadores de Cristo.", "practice": "Escreva: Eu sou ______ em Cristo. Complete 5 vezes.", "question": "Quem voc\u00ea \u00e9 quando ningu\u00e9m est\u00e1 vendo?"}'),
('6f54e6e9-2b46-44e2-aca6-1efbebe2d0e3', 'a1a1a1a1-3030-4000-8000-000000000001', 22, 'Dia 22 — Presença', 'Semana 4: Integrar', '{"pch": "Na tua presen\u00e7a h\u00e1 plenitude de alegria\u2026 Prop\u00f3sito come\u00e7a quando voc\u00ea est\u00e1 presente.", "verse": "Sl 16,11", "lectio": "Leia Sl 16. Deus \u00e9 a por\u00e7\u00e3o da heran\u00e7a.", "practice": "Viva hoje com aten\u00e7\u00e3o plena. Observe cada momento.", "question": "Em que momentos voc\u00ea se sente mais presente?"}'),
('6994196f-8d3c-4b7f-a609-4c26f0acc649', 'a1a1a1a1-3030-4000-8000-000000000001', 23, 'Dia 23 — Missão', 'Semana 4: Integrar', '{"pch": "Ide e fazei disc\u00edpulos\u2026 Sua vida \u00e9 sua maior mensagem.", "verse": "Mt 28,19", "lectio": "Leia Mt 28,16-20. A grande comiss\u00e3o.", "practice": "Escreva sua declara\u00e7\u00e3o de miss\u00e3o pessoal em 1 frase.", "question": "Se sua vida fosse uma mensagem, qual seria?"}'),
('b359357b-7017-498f-b4a5-ed558f7e910c', 'a1a1a1a1-3030-4000-8000-000000000001', 24, 'Dia 24 — Confiança', 'Semana 4: Integrar', '{"pch": "Confia no Senhor de todo o cora\u00e7\u00e3o\u2026 e Ele endireitar\u00e1 as tuas veredas.", "verse": "Pv 3,5-6", "lectio": "Leia Pv 3,1-8. Sabedoria vs. entendimento pr\u00f3prio.", "practice": "Entregue em ora\u00e7\u00e3o a \u00e1rea mais dif\u00edcil da sua vida.", "question": "Em que \u00e1rea voc\u00ea ainda n\u00e3o confiou a Deus?"}'),
('eed9da3a-776e-4f1d-a458-c9d651b640ca', 'a1a1a1a1-3030-4000-8000-000000000001', 25, 'Dia 25 — Perseverança', 'Semana 4: Integrar', '{"pch": "N\u00e3o nos cansemos de fazer o bem\u2026 porque a seu tempo colheremos. O prop\u00f3sito exige const\u00e2ncia.", "verse": "Gl 6,9", "lectio": "Leia Gl 6,7-10. A lei da semeadura.", "practice": "Retome algo que abandonou. D\u00ea mais um passo.", "question": "Em que voc\u00ea j\u00e1 desistiu cedo demais?"}'),
('abc5e0a3-7d65-4411-92c6-1bcd1dbadc5c', 'a1a1a1a1-3030-4000-8000-000000000001', 26, 'Dia 26 — Comunidade', 'Semana 4: Integrar', '{"pch": "Melhor \u00e9 serem dois do que um\u2026 Prop\u00f3sito isolado definha. Prop\u00f3sito compartilhado floresce.", "verse": "Ec 4,9-10", "lectio": "Leia Ec 4,9-12. A corda de tr\u00eas dobras.", "practice": "Convide algu\u00e9m para compartilhar sua jornada espiritual.", "question": "Quem caminha com voc\u00ea? Quem deveria caminhar?"}'),
('30bfc644-7672-461d-9694-0a1b3b0f00a1', 'a1a1a1a1-3030-4000-8000-000000000001', 27, 'Dia 27 — Legado', 'Semana 4: Integrar', '{"pch": "Combati o bom combate\u2026 completei a carreira. O que ficar\u00e1 quando voc\u00ea partir?", "verse": "2Tm 4,7", "lectio": "Leia 2Tm 4,6-8. Paulo olha para tr\u00e1s com paz.", "practice": "Escreva o que voc\u00ea quer que digam no seu funeral.", "question": "Que legado voc\u00ea quer deixar?"}'),
('4368c10d-fe86-468f-a43d-da8518d4ad35', 'a1a1a1a1-3030-4000-8000-000000000001', 28, 'Dia 28 — Gratidão', 'Semana 4: Integrar', '{"pch": "Em tudo dai gra\u00e7as\u2026 A gratid\u00e3o transforma a perspectiva e revela o prop\u00f3sito no cotidiano.", "verse": "1Ts 5,18", "lectio": "Leia 1Ts 5,16-24. Alegria, ora\u00e7\u00e3o e gratid\u00e3o.", "practice": "Escreva 10 motivos de gratid\u00e3o. Releia antes de dormir.", "question": "Pelo que voc\u00ea \u00e9 grato que nunca agradeceu?"}'),
('41a28ae5-52b9-407c-90d7-0a03b73b4a2a', 'a1a1a1a1-3030-4000-8000-000000000001', 29, 'Dia 29 — Compromisso', 'Semana 4: Integrar', '{"pch": "Ofere\u00e7am os seus corpos como sacrif\u00edcio vivo\u2026 Prop\u00f3sito sem compromisso \u00e9 fantasia.", "verse": "Rm 12,1", "lectio": "Leia Rm 12,1-2. Culto racional.", "practice": "Escreva 3 compromissos concretos para os pr\u00f3ximos 30 dias.", "question": "Com o que voc\u00ea se compromete a partir de hoje?"}'),
('0443b9b4-2ce3-415a-a730-2773c02f45c3', 'a1a1a1a1-3030-4000-8000-000000000001', 30, 'Dia 30 — Envio', 'Semana 4: Integrar', '{"pch": "Eis-me aqui, envia-me! Voc\u00ea n\u00e3o chegou ao fim\u2026 chegou ao come\u00e7o do que nasceu para viver.", "verse": "Is 6,8", "lectio": "Leia Is 6,1-8. A vis\u00e3o, a purifica\u00e7\u00e3o, o envio.", "practice": "Releia todas as suas reflex\u00f5es. Escreva uma carta para o seu eu de 30 dias atr\u00e1s.", "question": "Quem voc\u00ea se tornou nesses 30 dias?"}'),
('95b1090e-117c-4fd8-95ab-7b18071641cd', 'a1b2c3d4-0001-4000-8000-000000000001', 1, 'O Amor de Deus por Você', 'Descobrindo que somos amados', '{"bible_ref": "Jo 3,16", "reflection": "Deus nos amou primeiro. Medite sobre o que significa ser amado incondicionalmente."}'),
('e6c6deb4-e34a-429d-b30b-b65a615964eb', 'a1b2c3d4-0001-4000-8000-000000000001', 2, 'Primeira Oração', 'Aprendendo a conversar com Deus', '{"prayer": "Pai nosso", "instruction": "Reze lentamente, saboreando cada palavra."}'),
('65a76c6b-c1a8-46a3-907d-01704c71580b', 'a1b2c3d4-0001-4000-8000-000000000001', 3, 'A Palavra que Transforma', 'Introdução à Bíblia', '{"bible_ref": "Sl 119,105", "reflection": "A Palavra de Deus \u00e9 l\u00e2mpada para nossos passos."}'),
('8a7d7d4c-d0ca-400c-9da2-442febc6deaa', 'a1b2c3d4-0001-4000-8000-000000000001', 4, 'Exame de Consciência', 'Olhar para dentro com honestidade', '{"prompt": "O que mais me afasta de Deus no meu dia a dia?", "guidance": "Seja honesto consigo mesmo, sem julgamento."}'),
('38db9dd6-8288-4cb7-8ec2-1581cf639997', 'a1b2c3d4-0001-4000-8000-000000000001', 5, 'Os Sacramentos', 'Fontes de graça', '{"reflection": "Os sacramentos s\u00e3o sinais eficazes da gra\u00e7a divina.", "catechism_ref": "CIC 1210"}'),
('bfd8ee6c-4069-42a9-85ec-f5558311d60f', 'a1b2c3d4-0003-4000-8000-000000000003', 1, 'O Chamado à Contemplação', 'São João da Cruz', '{"text": "A alma que deseja alcan\u00e7ar a perfei\u00e7\u00e3o deve primeiro passar pela noite escura dos sentidos.", "source": "S\u00e3o Jo\u00e3o da Cruz"}'),
('7022626f-dd2e-4568-91b1-4eeccfc1b688', 'a1b2c3d4-0003-4000-8000-000000000003', 2, 'Oração de Quietude', 'Santa Teresa de Ávila', '{"instruction": "Feche os olhos, aquiete a mente e simplesmente esteja na presen\u00e7a de Deus por 20 minutos."}'),
('13e35790-a1aa-4ac7-bd61-6bdf6572b923', 'a1b2c3d4-0003-4000-8000-000000000003', 3, 'Lectio Divina Profunda', 'A Palavra que penetra a alma', '{"method": "Leia, medite, ore, contemple. Repita at\u00e9 sentir a Palavra falar ao seu cora\u00e7\u00e3o.", "bible_ref": "Jo 15,1-8"}'),
('d596428b-8081-4845-b0f1-581e8b574516', 'a1b2c3d4-0003-4000-8000-000000000003', 4, 'Diário Místico', 'Registre suas moções interiores', '{"prompt": "O que o Esp\u00edrito Santo est\u00e1 falando ao seu cora\u00e7\u00e3o? Que movimentos interiores voc\u00ea percebe?"}'),
('1e36c32b-9c60-4665-a21b-89eba8bdab35', 'a1b2c3d4-0003-4000-8000-000000000003', 5, 'A União com Deus', 'O fim da jornada é o começo', '{"text": "O importante n\u00e3o \u00e9 pensar muito, mas amar muito.", "source": "Santa Teresa de \u00c1vila", "catechism_ref": "CIC 2709"}'),
('b1b2c3d4-0001-4000-8000-000000000001', 'a1b2c3d4-0004-4000-8000-000000000004', 1, 'O Reconhecimento', 'Olhar para dentro com coragem', '{"intro": "Toda liberta\u00e7\u00e3o come\u00e7a com um ato de coragem: reconhecer que algo nos prende. N\u00e3o se trata de fraqueza \u2014 \u00e9 a mais profunda honestidade diante de Deus. Santo Agostinho escreveu: \"Fizeste-nos para Ti, Senhor, e o nosso cora\u00e7\u00e3o est\u00e1 inquieto enquanto n\u00e3o repousar em Ti.\" Essa inquieta\u00e7\u00e3o \u00e9 o primeiro sinal de que h\u00e1 correntes a serem rompidas.\n\nHoje, voc\u00ea \u00e9 convidado a parar. N\u00e3o para se julgar, mas para se ver. Como quem olha no espelho pela primeira vez sem desviar o olhar. O que te prende? Medo? Ressentimento? V\u00edcios? Padr\u00f5es que se repetem? Nomeie, sem vergonha. Deus j\u00e1 sabe \u2014 Ele espera que voc\u00ea tamb\u00e9m saiba.", "prayer": "Senhor, d\u00e1-me a coragem de olhar para dentro sem fugir. Mostra-me as correntes que eu mesmo n\u00e3o enxergo. N\u00e3o quero viver mais na superf\u00edcie \u2014 quero a verdade que liberta. Am\u00e9m.", "practice": "Encontre um lugar silencioso. Feche os olhos por 5 minutos e pe\u00e7a a Deus que ilumine uma \u00e1rea da sua vida onde voc\u00ea n\u00e3o \u00e9 livre. N\u00e3o force \u2014 apenas escute. Depois, escreva no seu di\u00e1rio o que veio ao cora\u00e7\u00e3o.", "scripture": "\"Conhecereis a verdade, e a verdade vos libertar\u00e1.\" \u2014 Jo 8,32\n\n\"Sonda-me, \u00f3 Deus, e conhece o meu cora\u00e7\u00e3o; prova-me e conhece os meus pensamentos.\" \u2014 Sl 139,23", "reflection": "1. Que padr\u00f5es se repetem na sua vida e te causam sofrimento?\n2. H\u00e1 algo que voc\u00ea evita olhar de frente? O que seria?\n3. Se Deus pudesse te dizer uma verdade agora, o que voc\u00ea acha que Ele diria?", "journal_prompt": "O que eu reconhe\u00e7o hoje que me prende? Qual \u00e9 a primeira corrente que consigo nomear?"}'),
('b1b2c3d4-0002-4000-8000-000000000002', 'a1b2c3d4-0004-4000-8000-000000000004', 2, 'As Correntes Invisíveis', 'Identificando o que nos aprisiona', '{"intro": "Existem pris\u00f5es com grades de ferro \u2014 e existem pris\u00f5es feitas de pensamentos, h\u00e1bitos e feridas. As mais perigosas s\u00e3o as que n\u00e3o vemos. S\u00e3o as narrativas que repetimos sobre n\u00f3s mesmos: \"eu n\u00e3o mere\u00e7o\", \"sempre ser\u00e1 assim\", \"Deus n\u00e3o se importa comigo\".\n\nS\u00e3o Tom\u00e1s de Aquino ensina que o pecado obscurece a raz\u00e3o e enfraquece a vontade. Mas n\u00e3o apenas o pecado nos prende: o medo, a vergonha, o orgulho, a autossufici\u00eancia \u2014 tudo isso cria correntes invis\u00edveis.\n\nHoje, vamos mapear essas correntes. N\u00e3o para nos condenar, mas para trazer \u00e0 luz o que vive na escurid\u00e3o.", "prayer": "Esp\u00edrito Santo, ilumina os cantos escuros da minha alma. Mostra-me as mentiras em que acreditei. Substitui cada corrente pela Tua verdade. Eu quero ser livre \u2014 verdadeiramente livre. Am\u00e9m.", "practice": "Pegue uma folha de papel e divida em duas colunas: \"O que eu acredito sobre mim\" e \"O que Deus diz sobre mim\". Preencha com honestidade. Compare as duas colunas e perceba onde est\u00e3o as distor\u00e7\u00f5es.", "scripture": "\"Onde est\u00e1 o Esp\u00edrito do Senhor, a\u00ed h\u00e1 liberdade.\" \u2014 2Cor 3,17\n\n\"N\u00e3o vos conformeis com este mundo, mas transformai-vos pela renova\u00e7\u00e3o da vossa mente.\" \u2014 Rm 12,2", "reflection": "1. Que mentiras voc\u00ea acredita sobre si mesmo h\u00e1 anos?\n2. Existe algum medo que controla suas decis\u00f5es?\n3. H\u00e1 algum relacionamento ou situa\u00e7\u00e3o que te mant\u00e9m preso(a) a um padr\u00e3o destrutivo?", "journal_prompt": "Quais s\u00e3o as mentiras que descobri que acreditava sobre mim? Como elas afetaram minhas escolhas?"}'),
('b1b2c3d4-0003-4000-8000-000000000003', 'a1b2c3d4-0004-4000-8000-000000000004', 3, 'O Espelho da Alma', 'Enfrentando a verdade sobre quem somos', '{"intro": "O exame de consci\u00eancia \u00e9 a pr\u00e1tica mais antiga e poderosa da vida crist\u00e3. Santo In\u00e1cio de Loyola o considerava mais importante que a pr\u00f3pria ora\u00e7\u00e3o \u2014 porque sem verdade, a ora\u00e7\u00e3o se torna fuga.\n\nHoje, vamos fazer algo radical: olhar para a alma como se olh\u00e1ssemos num espelho sem filtros. N\u00e3o \u00e9 autocondena\u00e7\u00e3o \u2014 \u00e9 autoconsci\u00eancia na presen\u00e7a de Deus. Como diz Santa Teresa de \u00c1vila: \"O autoconhecimento \u00e9 a porta da ora\u00e7\u00e3o.\"", "prayer": "Jesus manso e humilde de cora\u00e7\u00e3o, fazei o meu cora\u00e7\u00e3o semelhante ao Vosso. N\u00e3o me deixes fugir da verdade. D\u00e1-me a gra\u00e7a de me ver como Tu me v\u00eas \u2014 com amor e com verdade. Am\u00e9m.", "practice": "Fa\u00e7a o Exame de Consci\u00eancia de Santo In\u00e1cio: 1) Agrade\u00e7a as gra\u00e7as do dia. 2) Pe\u00e7a luz para ver seus atos. 3) Reveja as \u00faltimas 24 horas. 4) Pe\u00e7a perd\u00e3o pelo que errou. 5) Proponha-se a melhorar amanh\u00e3.", "scripture": "\"Examina-me, \u00f3 Deus, e conhece o meu cora\u00e7\u00e3o. Prova-me e conhece os meus pensamentos ansiosos. V\u00ea se h\u00e1 em mim algum caminho mau e guia-me pelo caminho eterno.\" \u2014 Sl 139,23-24", "reflection": "1. Se algu\u00e9m filmasse sua vida interior por uma semana, o que veria?\n2. Qual \u00e9 o pecado que voc\u00ea mais justifica para si mesmo?\n3. H\u00e1 algo que voc\u00ea nunca confessou \u2014 n\u00e3o por esquecimento, mas por vergonha?", "journal_prompt": "O que o espelho da alma me mostrou hoje? O que preciso levar ao sacramento da confiss\u00e3o?"}'),
('b1b2c3d4-0004-4000-8000-000000000004', 'a1b2c3d4-0004-4000-8000-000000000004', 4, 'A Porta Estreita', 'O caminho da renúncia e da entrega', '{"intro": "\"Entrai pela porta estreita\" \u2014 esta palavra de Jesus n\u00e3o \u00e9 um convite ao sofrimento gratuito, mas \u00e0 escolha consciente. A porta larga \u00e9 a comodidade, o \"deixa pra l\u00e1\", o conformismo espiritual. A porta estreita \u00e9 a decis\u00e3o de morrer para si mesmo.\n\nS\u00e3o Jo\u00e3o da Cruz chamou isso de \"noite escura da alma\" \u2014 o momento em que Deus nos convida a soltar o que nos d\u00e1 falsa seguran\u00e7a para encontrar a verdadeira. \u00c9 doloroso. Mas \u00e9 o \u00fanico caminho para a liberdade.", "prayer": "Senhor Jesus, Tu passaste pela porta estreita da Cruz por amor a mim. D\u00e1-me a coragem de fazer o mesmo. N\u00e3o quero a comodidade que me afasta de Ti. Quero a estreiteza que me aproxima. Am\u00e9m.", "practice": "Escolha uma ren\u00fancia concreta para esta semana. Pode ser algo pequeno: um v\u00edcio digital, uma comodidade, um padr\u00e3o de consumo. Ofere\u00e7a essa ren\u00fancia a Deus como sacrif\u00edcio de amor. Registre como se sente ao longo dos dias.", "scripture": "\"Entrai pela porta estreita, pois larga \u00e9 a porta e espa\u00e7oso o caminho que conduz \u00e0 perdi\u00e7\u00e3o, e muitos s\u00e3o os que entram por ela.\" \u2014 Mt 7,13\n\n\"Se algu\u00e9m quiser vir ap\u00f3s mim, negue-se a si mesmo, tome a sua cruz e siga-me.\" \u2014 Mt 16,24", "reflection": "1. O que voc\u00ea mais tem medo de perder? Essa coisa tem poder sobre voc\u00ea?\n2. Que conforto ou h\u00e1bito Deus est\u00e1 te pedindo para soltar?\n3. O que significa \"morrer para si mesmo\" na sua vida concreta?", "journal_prompt": "Qual ren\u00fancia escolhi para esta semana? O que sinto ao pensar em abrir m\u00e3o disso?"}'),
('b1b2c3d4-0005-4000-8000-000000000005', 'a1b2c3d4-0004-4000-8000-000000000004', 5, 'O Perdão Radical', 'Quebrando a maior corrente de todas', '{"intro": "Se h\u00e1 uma corrente que prende mais almas do que qualquer outra, \u00e9 a falta de perd\u00e3o. O ressentimento \u00e9 um veneno que bebemos esperando que o outro morra. E no entanto, quantos de n\u00f3s carregamos m\u00e1goas de anos \u2014 contra pais, amigos, ex-parceiros, contra n\u00f3s mesmos, e at\u00e9 contra Deus?\n\nJesus n\u00e3o sugeriu o perd\u00e3o \u2014 Ele o ordenou. E n\u00e3o uma vez, mas setenta vezes sete. Porque o perd\u00e3o n\u00e3o \u00e9 um sentimento: \u00e9 uma decis\u00e3o da vontade, sustentada pela gra\u00e7a. Hoje, vamos enfrentar a maior corrente.", "prayer": "Pai misericordioso, Tu que perdoaste a humanidade inteira do alto da Cruz, d\u00e1-me a gra\u00e7a de perdoar quem me feriu. Cura as feridas que carrego. Liberta-me do peso do ressentimento. Eu escolho perdoar \u2014 n\u00e3o porque seja f\u00e1cil, mas porque Tu me pedes. Am\u00e9m.", "practice": "Escreva uma carta de perd\u00e3o (que n\u00e3o precisa ser enviada). Dirija-se \u00e0 pessoa que te feriu. Descreva a dor, reconhe\u00e7a a ferida, e ent\u00e3o escreva as palavras: \"Eu escolho te perdoar. Entrego esta dor a Deus.\" Depois, reze um Pai-Nosso lentamente, detendo-se em \"perdoai as nossas ofensas assim como n\u00f3s perdoamos a quem nos tem ofendido.\"", "scripture": "\"Se perdoardes aos homens as suas ofensas, vosso Pai celeste tamb\u00e9m vos perdoar\u00e1.\" \u2014 Mt 6,14\n\n\"Pai, perdoa-lhes, porque n\u00e3o sabem o que fazem.\" \u2014 Lc 23,34", "reflection": "1. Quem voc\u00ea ainda n\u00e3o perdoou de verdade?\n2. Voc\u00ea se perdoou pelos seus pr\u00f3prios erros?\n3. H\u00e1 alguma m\u00e1goa contra Deus \u2014 por algo que Ele permitiu acontecer?", "journal_prompt": "Quem eu perdoei hoje? Como me senti ao escrever a carta de perd\u00e3o? O que mudou dentro de mim?"}'),
('b1b2c3d4-0006-4000-8000-000000000006', 'a1b2c3d4-0004-4000-8000-000000000004', 6, 'A Liberdade dos Filhos', 'Vivendo como quem foi libertado', '{"intro": "Voc\u00ea chegou ao fim desta jornada \u2014 mas na verdade, este \u00e9 o come\u00e7o. A liberdade que Cristo oferece n\u00e3o \u00e9 aus\u00eancia de dificuldades: \u00e9 a presen\u00e7a de Deus em cada uma delas. Como diz S\u00e3o Paulo: \"Para a liberdade \u00e9 que Cristo nos libertou. Permanecei firmes e n\u00e3o vos submetais de novo ao jugo da escravid\u00e3o.\"\n\nAgora que voc\u00ea reconheceu suas correntes, olhou de frente para a verdade, passou pela porta estreita e perdoou \u2014 \u00e9 hora de viver como filho(a) livre. N\u00e3o como escravo do medo, da culpa ou do passado. Mas como herdeiro(a) do Reino.", "prayer": "Senhor Jesus Cristo, Libertador da minha alma, obrigado(a) por esta jornada. Obrigado(a) por me mostrar a verdade, mesmo quando doeu. Obrigado(a) por romper as correntes que me prendiam. Eu me comprometo a viver na liberdade que Tu me deste. N\u00e3o voltarei atr\u00e1s. Am\u00e9m.", "practice": "Crie um \"plano de liberdade\": 1) Uma pr\u00e1tica di\u00e1ria de ora\u00e7\u00e3o (5 min). 2) Um exame de consci\u00eancia semanal. 3) Confiss\u00e3o mensal. 4) Uma pessoa de confian\u00e7a para prestar contas. Comprometa-se com este plano por 30 dias.", "scripture": "\"Para a liberdade \u00e9 que Cristo nos libertou. Permanecei firmes e n\u00e3o vos submetais de novo ao jugo da escravid\u00e3o.\" \u2014 Gl 5,1\n\n\"Se o Filho vos libertar, verdadeiramente sereis livres.\" \u2014 Jo 8,36", "reflection": "1. O que mudou em voc\u00ea desde o in\u00edcio desta jornada?\n2. Quais correntes foram rompidas? Quais ainda precisam de trabalho?\n3. Como voc\u00ea vai manter essa liberdade no dia a dia?", "journal_prompt": "O que esta jornada significou para mim? Qual \u00e9 meu compromisso a partir de agora? Que palavras eu diria a algu\u00e9m que est\u00e1 come\u00e7ando onde eu comecei?"}'),
('8197c079-be7b-4fe0-b6b6-52fca2c2ad2d', 'a1b2c3d4-1111-4000-8000-000000000001', 1, 'O Despertar Interior', 'Por que uma rotina espiritual?', '{"intro": "Antes de tudo, precisamos entender: uma rotina espiritual n\u00e3o \u00e9 uma pris\u00e3o de hor\u00e1rios \u2014 \u00e9 uma estrutura que liberta. Assim como um rio precisa de margens para fluir com for\u00e7a, nossa vida espiritual precisa de ritmo para crescer. Santo In\u00e1cio de Loyola dizia que a ordem do dia \u00e9 a primeira vit\u00f3ria contra o caos interior. Quando estabelecemos momentos fixos de encontro com Deus, deixamos de depender da emo\u00e7\u00e3o e passamos a viver pela decis\u00e3o.", "prayer": "Senhor, ensina-me a Te buscar n\u00e3o quando sobra tempo, mas como a primeira coisa do meu dia. Que eu aprenda a construir minha vida sobre o alicerce da Tua presen\u00e7a. Am\u00e9m.", "practice": "Escolha dois hor\u00e1rios fixos hoje \u2014 manh\u00e3 e noite \u2014 e reserve pelo menos 5 minutos em cada para sil\u00eancio e ora\u00e7\u00e3o.", "scripture": "\"Buscai primeiro o Reino de Deus e a sua justi\u00e7a, e todas estas coisas vos ser\u00e3o acrescentadas.\" \u2014 Mt 6,33", "reflection": "Em que momentos do seu dia voc\u00ea sente que Deus est\u00e1 mais distante? Que horas seriam ideais para reservar um encontro di\u00e1rio com Ele?"}'),
('6df20be7-3248-4db0-88cb-13265ffc745b', 'a1b2c3d4-1111-4000-8000-000000000001', 2, 'Oração da Manhã', 'Começando o dia com Deus', '{"intro": "A tradi\u00e7\u00e3o crist\u00e3 sempre valorizou a ora\u00e7\u00e3o matutina. Os monges beneditinos iniciam o dia com as Laudes antes do sol nascer. Por qu\u00ea? Porque oferecer as prim\u00edcias do dia a Deus \u00e9 reconhecer que tudo vem Dele. Uma ora\u00e7\u00e3o matinal simples \u2014 mesmo de 5 minutos \u2014 transforma a qualidade do seu dia inteiro. N\u00e3o precisa ser longa; precisa ser sincera.", "prayer": "Deus de toda gra\u00e7a, que as primeiras palavras da minha boca sejam de louvor. Que eu aprenda com Jesus a buscar-Te antes de tudo. Am\u00e9m.", "practice": "Amanh\u00e3, ao despertar, antes de olhar o celular, fa\u00e7a esta ora\u00e7\u00e3o: Pai, entrego este dia nas Tuas m\u00e3os. Guia meus passos, meus pensamentos e minhas palavras.", "scripture": "\"De manh\u00e3, por\u00e9m, tendo-se levantado muito cedo, saiu e foi a um lugar deserto, e ali orava.\" \u2014 Mc 1,35", "reflection": "Como voc\u00ea normalmente come\u00e7a seu dia? O que mudaria se os primeiros 5 minutos fossem dedicados a Deus?"}'),
('bfe0188e-4821-488d-8502-86fa2e397217', 'a1b2c3d4-1111-4000-8000-000000000001', 3, 'Lectio Divina Diária', 'Alimentando-se da Palavra', '{"intro": "A Lectio Divina \u00e9 um m\u00e9todo milenar de leitura orante da B\u00edblia. Diferente do estudo acad\u00eamico, ela busca o encontro pessoal com Deus atrav\u00e9s do texto sagrado. S\u00e3o quatro passos: Leitura (lectio), Medita\u00e7\u00e3o (meditatio), Ora\u00e7\u00e3o (oratio) e Contempla\u00e7\u00e3o (contemplatio). Mesmo 10 minutos por dia com este m\u00e9todo podem revolucionar sua rela\u00e7\u00e3o com a Escritura.", "prayer": "Esp\u00edrito Santo, abre meus olhos para ver as maravilhas da Tua lei. Que a Tua Palavra n\u00e3o seja apenas texto, mas vida para minha alma. Am\u00e9m.", "practice": "Escolha um Evangelho (sugerimos Marcos, o mais curto). Leia apenas um par\u00e1grafo por dia usando os 4 passos da Lectio Divina. Anote uma frase que tocou seu cora\u00e7\u00e3o.", "scripture": "\"L\u00e2mpada para os meus p\u00e9s \u00e9 a tua palavra, e luz para o meu caminho.\" \u2014 Sl 119,105", "reflection": "Qual foi a \u00faltima vez que uma passagem b\u00edblica realmente tocou seu cora\u00e7\u00e3o? O que aconteceria se voc\u00ea fizesse isso diariamente?"}'),
('9f4f5035-2c4d-4b3b-9464-3406780937d7', 'a1b2c3d4-1111-4000-8000-000000000001', 4, 'O Exame de Consciência', 'Olhando o dia com os olhos de Deus', '{"intro": "O Exame de Consci\u00eancia, popularizado por Santo In\u00e1cio, \u00e9 uma ora\u00e7\u00e3o noturna poderosa. Em 5 passos simples, voc\u00ea revisa o dia com gratid\u00e3o, reconhece as mo\u00e7\u00f5es interiores, identifica onde falhou e planeja o amanh\u00e3. N\u00e3o \u00e9 uma sess\u00e3o de culpa \u2014 \u00e9 um momento de honestidade amorosa diante de Deus. Muitos santos consideravam esta a ora\u00e7\u00e3o mais importante do dia.", "prayer": "Senhor, ajuda-me a ver meu dia com Teus olhos. Onde falhei, d\u00e1-me Teu perd\u00e3o. Onde acertei, d\u00e1-me Tua humildade. Am\u00e9m.", "practice": "Hoje \u00e0 noite, fa\u00e7a o Exame em 5 passos: 1) Agrade\u00e7a; 2) Pe\u00e7a luz ao Esp\u00edrito; 3) Reveja o dia; 4) Pe\u00e7a perd\u00e3o; 5) Planeje o amanh\u00e3 com Deus.", "scripture": "\"Examina-me, \u00f3 Deus, e conhece o meu cora\u00e7\u00e3o; prova-me e conhece os meus pensamentos.\" \u2014 Sl 139,23", "reflection": "No final do dia, como voc\u00ea se sente? Consegue identificar momentos em que Deus agiu na sua vida hoje?"}'),
('635e9a5e-6ba8-4189-ad69-2cdceb7f330a', 'a1b2c3d4-1111-4000-8000-000000000001', 5, 'Jejum e Silêncio', 'Esvaziando para ser preenchido', '{"intro": "O jejum n\u00e3o \u00e9 apenas abstin\u00eancia de comida \u2014 \u00e9 uma pr\u00e1tica de esvaziamento que abre espa\u00e7o para Deus. Jesus jejuou 40 dias no deserto antes de iniciar seu minist\u00e9rio. O sil\u00eancio interior, por sua vez, \u00e9 o terreno f\u00e9rtil onde a voz de Deus pode ser ouvida. Numa cultura de ru\u00eddo constante, aprender a silenciar \u00e9 um ato revolucion\u00e1rio de f\u00e9.", "prayer": "Deus do sil\u00eancio, ensina-me a esvaziar-me para ser preenchido por Ti. Que eu encontre no vazio a Tua plenitude. Am\u00e9m.", "practice": "Escolha um jejum para esta semana: redes sociais por 1 dia, ou sil\u00eancio de 30 minutos (sem m\u00fasica, sem podcast, sem conversa). Observe o que acontece no seu interior.", "scripture": "\"Mas tu, quando jejuares, unge a cabe\u00e7a e lava o rosto, para que n\u00e3o pare\u00e7as aos homens que jejuas.\" \u2014 Mt 6,17-18", "reflection": "De que forma o barulho (externo e interno) dificulta seu encontro com Deus? O que voc\u00ea poderia \"jejuar\" al\u00e9m de comida?"}'),
('39047abc-687a-4ad8-91f5-f383049ef091', 'a1b2c3d4-1111-4000-8000-000000000001', 6, 'Perseverança na Rotina', 'Quando a motivação acaba, a disciplina começa', '{"intro": "A maior tenta\u00e7\u00e3o da vida espiritual n\u00e3o \u00e9 o pecado grave \u2014 \u00e9 a mediocridade. \u00c9 o dia em que voc\u00ea \"n\u00e3o est\u00e1 com vontade\". Santa Teresa de \u00c1vila confessou que, por anos, sua ora\u00e7\u00e3o era \u00e1rida e sem consola\u00e7\u00e3o. Mas ela perseverou. E foi nos desertos que encontrou as maiores gra\u00e7as. A rotina espiritual n\u00e3o depende de sentir \u2014 depende de decidir, todos os dias.", "prayer": "Senhor, quando a aridez vier, lembra-me que Tu est\u00e1s presente mesmo no sil\u00eancio. D\u00e1-me a gra\u00e7a da perseveran\u00e7a. Am\u00e9m.", "practice": "Escreva sua Regra de Vida pessoal: hor\u00e1rio de ora\u00e7\u00e3o, leitura b\u00edblica, exame de consci\u00eancia. Cole em um lugar vis\u00edvel. Comprometa-se por 21 dias.", "scripture": "\"Aquele que perseverar at\u00e9 o fim, esse ser\u00e1 salvo.\" \u2014 Mt 24,13", "reflection": "Qual \u00e9 sua maior dificuldade para manter uma rotina espiritual? O que te faria n\u00e3o desistir mesmo nos dias dif\u00edceis?"}'),
('e01f8f74-61fe-4d25-b27d-72112e86ecd4', 'a1b2c3d4-2222-4000-8000-000000000002', 1, 'O que é Oração?', 'Redescubrindo o diálogo com Deus', '{"intro": "Santa Teresa de \u00c1vila definiu ora\u00e7\u00e3o como \"um trato de amizade com Aquele que sabemos que nos ama\". N\u00e3o \u00e9 uma f\u00f3rmula m\u00e1gica nem uma lista de pedidos \u2014 \u00e9 um relacionamento. Assim como qualquer amizade, exige tempo, presen\u00e7a e sinceridade. O Catecismo ensina que ora\u00e7\u00e3o \u00e9 a eleva\u00e7\u00e3o da alma a Deus (CIC 2559). Mas antes de elevar, precisamos reconhecer: somos amados antes de orar.", "prayer": "Senhor, ensina-me a rezar. Que eu descubra que antes de eu Te procurar, Tu j\u00e1 me encontraste. Am\u00e9m.", "practice": "Reserve 10 minutos hoje para simplesmente estar na presen\u00e7a de Deus. Sem pedir nada. Sem dizer nada. Apenas estar.", "scripture": "\"Eis que estou \u00e0 porta e bato. Se algu\u00e9m ouvir a minha voz e abrir a porta, entrarei em sua casa e cearei com ele, e ele comigo.\" \u2014 Ap 3,20", "reflection": "Se ora\u00e7\u00e3o \u00e9 amizade, como est\u00e1 sua amizade com Deus hoje? Voc\u00ea fala mais ou escuta mais?"}'),
('9e816128-a358-40a7-ae0f-8063a050e04f', 'a1b2c3d4-2222-4000-8000-000000000002', 2, 'Oração Vocal', 'As palavras que nos unem ao céu', '{"intro": "A ora\u00e7\u00e3o vocal \u00e9 a forma mais acess\u00edvel de rezar. O Pai Nosso, a Ave Maria, o Gl\u00f3ria \u2014 s\u00e3o ora\u00e7\u00f5es que Jesus e a Igreja nos ensinaram. Mas aten\u00e7\u00e3o: rezar vocalmente n\u00e3o \u00e9 repetir palavras vazias. Jesus alertou contra a \"v\u00e3 repeti\u00e7\u00e3o\" (Mt 6,7). A chave \u00e9 unir l\u00e1bios e cora\u00e7\u00e3o. Santo Agostinho dizia: \"Quem canta, reza duas vezes\". A ora\u00e7\u00e3o vocal \u00e9 porta de entrada para profundidades maiores.", "prayer": "Pai nosso que est\u00e1s nos c\u00e9us... ensina-me a dizer estas palavras n\u00e3o com os l\u00e1bios apenas, mas com toda a minha alma. Am\u00e9m.", "practice": "Reze o Pai Nosso cinco vezes, mas muito devagar. A cada frase, pare e reflita sobre o que est\u00e1 dizendo. Anote qual frase mais tocou seu cora\u00e7\u00e3o.", "scripture": "\"V\u00f3s, pois, orai assim: Pai nosso, que est\u00e1s nos c\u00e9us, santificado seja o teu nome...\" \u2014 Mt 6,9", "reflection": "Qual ora\u00e7\u00e3o vocal voc\u00ea mais reza? Consegue rez\u00e1-la devagar, sentindo cada palavra?"}'),
('7fca0786-62cd-40f5-bdb5-ef6c0ddd152b', 'a1b2c3d4-2222-4000-8000-000000000002', 3, 'Oração Mental', 'O silêncio que transforma', '{"intro": "A ora\u00e7\u00e3o mental \u00e9 a conversa \u00edntima da alma com Deus \u2014 sem f\u00f3rmulas, sem textos decorados. \u00c9 o cora\u00e7\u00e3o que fala ao Cora\u00e7\u00e3o. Santa Teresa de Jesus dizia que muitos abandonam a ora\u00e7\u00e3o mental por acharem que n\u00e3o sabem fazer \u2014 mas basta \"olhar para Ele que nos olha\". A ora\u00e7\u00e3o mental n\u00e3o exige erudi\u00e7\u00e3o; exige humildade e desejo. Mesmo 5 minutos de ora\u00e7\u00e3o mental valem mais que horas de distra\u00e7\u00e3o.", "prayer": "Jesus manso e humilde de cora\u00e7\u00e3o, fazei o meu cora\u00e7\u00e3o semelhante ao Vosso. Ensina-me o sil\u00eancio que cura e transforma. Am\u00e9m.", "practice": "Sente-se em sil\u00eancio. Feche os olhos. Imagine Jesus sentado ao seu lado. Diga-Lhe o que est\u00e1 no seu cora\u00e7\u00e3o. Depois, fique em sil\u00eancio e escute. 10 minutos.", "scripture": "\"Mas tu, quando orares, entra no teu quarto, fecha a porta e ora a teu Pai em segredo; e teu Pai, que v\u00ea em segredo, te recompensar\u00e1.\" \u2014 Mt 6,6", "reflection": "Voc\u00ea j\u00e1 experimentou o sil\u00eancio interior na ora\u00e7\u00e3o? O que acontece quando voc\u00ea tenta ficar em sil\u00eancio diante de Deus?"}'),
('550f63c0-0129-410d-b548-e854e0b1ca80', 'a1b2c3d4-2222-4000-8000-000000000002', 4, 'O Rosário Contemplativo', 'Maria como mestra de oração', '{"intro": "O Ros\u00e1rio n\u00e3o \u00e9 mera repeti\u00e7\u00e3o \u2014 \u00e9 contempla\u00e7\u00e3o dos mist\u00e9rios de Cristo atrav\u00e9s dos olhos de Maria. S\u00e3o Jo\u00e3o Paulo II, em sua enc\u00edclica Rosarium Virginis Mariae, chamou o Ros\u00e1rio de \"comp\u00eandio do Evangelho\". Cada dezena \u00e9 uma janela para um momento da vida de Jesus. O segredo \u00e9 contemplar, n\u00e3o apenas contar. Quando rezado com o cora\u00e7\u00e3o, o Ros\u00e1rio se torna uma escola de ora\u00e7\u00e3o profunda.", "prayer": "Maria, minha M\u00e3e, ensina-me a contemplar teu Filho como tu o contemplavas. Que cada Ave-Maria seja um passo mais perto do Cora\u00e7\u00e3o de Jesus. Am\u00e9m.", "practice": "Reze uma dezena do Ros\u00e1rio (10 Ave-Marias) contemplando um mist\u00e9rio. Antes de come\u00e7ar, leia a passagem b\u00edblica correspondente. Imagine-se na cena.", "scripture": "\"Maria, por\u00e9m, guardava todas estas coisas, meditando-as no seu cora\u00e7\u00e3o.\" \u2014 Lc 2,19", "reflection": "Qual mist\u00e9rio do Ros\u00e1rio mais fala ao seu cora\u00e7\u00e3o hoje? Por que esse mist\u00e9rio te toca?"}'),
('bee9bcec-b493-48d8-bf5b-8ab8189fe025', 'a1b2c3d4-2222-4000-8000-000000000002', 5, 'Oração de Intercessão', 'Rezar pelos outros como Jesus reza por nós', '{"intro": "Jesus vive para interceder por n\u00f3s (Hb 7,25). Quando rezamos pelos outros, participamos da miss\u00e3o sacerdotal de Cristo. A intercess\u00e3o n\u00e3o \u00e9 informar Deus sobre problemas \u2014 Ele j\u00e1 sabe. \u00c9 unir nosso cora\u00e7\u00e3o ao Dele, carregando juntos o peso do mundo. Santos como Padre Pio recebiam milhares de inten\u00e7\u00f5es e as levavam ao altar. Cada intercess\u00e3o \u00e9 um ato de amor concreto.", "prayer": "Senhor, coloco diante de Ti todos aqueles que carrego no cora\u00e7\u00e3o. Cura, liberta, consola e transforma pela Tua miseric\u00f3rdia. Am\u00e9m.", "practice": "Fa\u00e7a uma lista de 5 pessoas que precisam de ora\u00e7\u00e3o. Reserve 2 minutos para cada uma. Apresente-as a Deus com amor, n\u00e3o com ansiedade.", "scripture": "\"Eu vos digo: Pedi e vos ser\u00e1 dado; buscai e achareis; batei e vos ser\u00e1 aberto.\" \u2014 Lc 11,9", "reflection": "Por quem voc\u00ea sente que Deus est\u00e1 pedindo que reze? H\u00e1 algu\u00e9m que precisa das suas ora\u00e7\u00f5es agora?"}'),
('fd5600a3-0646-49ae-b83c-b48815bd4835', 'a1b2c3d4-2222-4000-8000-000000000002', 6, 'Perseverança na Oração', 'Quando Deus parece silencioso', '{"intro": "Todo orante passa pelo deserto \u2014 a \"noite escura\" de S\u00e3o Jo\u00e3o da Cruz. S\u00e3o momentos em que Deus parece ausente, a ora\u00e7\u00e3o parece vazia e o cora\u00e7\u00e3o est\u00e1 seco. Mas \u00e9 justamente a\u00ed que a f\u00e9 se purifica. Madre Teresa de Calcut\u00e1 viveu 50 anos de aridez espiritual \u2014 e nunca deixou de rezar. A perseveran\u00e7a na ora\u00e7\u00e3o n\u00e3o \u00e9 hero\u00edsmo; \u00e9 confian\u00e7a de que Deus est\u00e1 trabalhando no escuro.", "prayer": "Deus fiel, mesmo quando n\u00e3o Te sinto, sei que est\u00e1s aqui. D\u00e1-me a gra\u00e7a de perseverar na ora\u00e7\u00e3o, confiando que Tu ages no sil\u00eancio. Am\u00e9m.", "practice": "Fa\u00e7a um compromisso escrito: \"Eu me comprometo a rezar todos os dias, por pelo menos 10 minutos, durante os pr\u00f3ximos 30 dias \u2014 mesmo quando n\u00e3o sentir vontade.\" Assine e date.", "scripture": "\"Vigia e ora, para que n\u00e3o entreis em tenta\u00e7\u00e3o. O esp\u00edrito est\u00e1 pronto, mas a carne \u00e9 fraca.\" \u2014 Mt 26,41", "reflection": "Voc\u00ea j\u00e1 passou por per\u00edodos de aridez na ora\u00e7\u00e3o? Como reagiu? O que aprendeu com isso?"}'),
('c1c2c3d4-3301-4000-8000-000000000001', 'b1b2c3d4-3333-4000-8000-000000000003', 1, 'O que é Vocação?', 'Fundamentos do chamado divino', '{"text": "A voca\u00e7\u00e3o n\u00e3o \u00e9 apenas uma profiss\u00e3o ou estado de vida \u2014 \u00e9 o chamado \u00fanico e irrepet\u00edvel que Deus faz a cada pessoa. Santo Tom\u00e1s de Aquino ensina que Deus nos criou com um prop\u00f3sito espec\u00edfico, inscrito em nossa pr\u00f3pria natureza.\n\n\"Deus n\u00e3o nos chama porque somos bons; Ele nos torna bons porque nos chama.\" \u2014 S\u00e3o Jo\u00e3o Cris\u00f3stomo\n\nExistem quatro voca\u00e7\u00f5es fundamentais na Igreja:\n1. **Matrim\u00f4nio** \u2014 chamado \u00e0 santidade conjugal e familiar\n2. **Sacerd\u00f3cio** \u2014 chamado a servir como alter Christus\n3. **Vida Consagrada** \u2014 chamado \u00e0 radicalidade evang\u00e9lica\n4. **Vida Leiga** \u2014 chamado \u00e0 santifica\u00e7\u00e3o no mundo\n\nO discernimento come\u00e7a com a disposi\u00e7\u00e3o de dizer: \"Senhor, o que queres que eu fa\u00e7a?\" (At 9,6)", "scripture": "Jr 1,5 \u2014 Antes de te formar no ventre materno, eu te conheci; antes de sa\u00edres do seio, eu te consagrei."}'),
('c1c2c3d4-3302-4000-8000-000000000002', 'b1b2c3d4-3333-4000-8000-000000000003', 2, 'Oração de Entrega', 'Colocar-se diante de Deus', '{"text": "Senhor Jesus Cristo,\nV\u00f3s que me chamais pelo nome,\nque me conheceis antes de eu nascer,\nconcedei-me a gra\u00e7a de ouvir Vossa voz\nno sil\u00eancio do meu cora\u00e7\u00e3o.\n\nTirai de mim todo medo,\ntoda resist\u00eancia,\ntodo apego \u00e0 minha vontade pr\u00f3pria.\n\nQuero apenas o que V\u00f3s quereis para mim.\nFazei de mim instrumento d\u00f3cil\nnas Vossas m\u00e3os.\n\nMaria, M\u00e3e do discernimento,\nque disseste o \"sim\" perfeito,\nintercessora por mim nesta jornada.\n\nAm\u00e9m.", "instruction": "Reze esta ora\u00e7\u00e3o lentamente, em ambiente silencioso. Repita as partes que tocarem seu cora\u00e7\u00e3o."}'),
('c1c2c3d4-3303-4000-8000-000000000003', 'b1b2c3d4-3333-4000-8000-000000000003', 3, 'Sinais do Chamado', 'Como Deus fala conosco', '{"text": "Santo In\u00e1cio de Loyola, mestre do discernimento, ensina que Deus nos fala de diversas maneiras:\n\n**1. Consola\u00e7\u00e3o Espiritual**\nUm sentimento profundo de paz, alegria e atra\u00e7\u00e3o por determinado caminho. N\u00e3o \u00e9 euforia passageira, mas uma serenidade duradoura.\n\n**2. Desola\u00e7\u00e3o Espiritual**\nInquieta\u00e7\u00e3o, tristeza, confus\u00e3o \u2014 sinais de que algo n\u00e3o est\u00e1 alinhado com a vontade de Deus.\n\n**3. Mo\u00e7\u00f5es Interiores**\nDesejos persistentes que surgem na ora\u00e7\u00e3o e se confirmam com o tempo.\n\n**4. Sinais Exteriores**\nCircunst\u00e2ncias providenciais, conselhos de diretores espirituais, portas que se abrem ou fecham.\n\n\"Em tempo de desola\u00e7\u00e3o, nunca fazer mudan\u00e7a.\" \u2014 Santo In\u00e1cio\n\nO discernimento requer paci\u00eancia. Deus n\u00e3o tem pressa.", "scripture": "1Rs 19,11-13 \u2014 O Senhor n\u00e3o estava no vento, nem no terremoto, nem no fogo... mas na brisa suave."}'),
('c1c2c3d4-3304-4000-8000-000000000004', 'b1b2c3d4-3333-4000-8000-000000000003', 4, 'Reflexão: Minha História Vocacional', 'Olhar para trás para enxergar adiante', '{"text": "Reflita sobre sua hist\u00f3ria pessoal \u00e0 luz do chamado de Deus:\n\n1. **Quais momentos da minha vida me trouxeram maior paz e realiza\u00e7\u00e3o?**\n2. **Quando me senti mais pr\u00f3ximo de Deus?**\n3. **Que talentos e dons recebi que poderiam servir aos outros?**\n4. **H\u00e1 algum desejo persistente no meu cora\u00e7\u00e3o que nunca desaparece?**\n5. **O que as pessoas que me conhecem bem dizem sobre meus dons?**\n\nEscreva suas respostas no di\u00e1rio espiritual. N\u00e3o tenha pressa \u2014 o discernimento \u00e9 um processo.", "prompt": "Descreva um momento em que voc\u00ea sentiu profundamente que Deus estava falando com voc\u00ea. O que aconteceu? Como se sentiu?"}'),
('c1c2c3d4-3305-4000-8000-000000000005', 'b1b2c3d4-3333-4000-8000-000000000003', 5, 'Modelos de Vocação', 'Santos que discerniram', '{"text": "Grandes santos passaram por intensos processos de discernimento:\n\n**Santo Agostinho** \u2014 Lutou anos entre a vida mundana e o chamado divino at\u00e9 sua convers\u00e3o no jardim de Mil\u00e3o: \"Tarde te amei, \u00f3 Beleza t\u00e3o antiga e t\u00e3o nova!\"\n\n**Santa Teresa de Lisieux** \u2014 Desde crian\u00e7a sentiu o chamado ao Carmelo, mas precisou superar obst\u00e1culos e esperar o tempo de Deus.\n\n**S\u00e3o Francisco de Assis** \u2014 Filho de comerciante rico, ouviu Cristo dizer: \"Francisco, vai e repara minha Igreja.\" Abandonou tudo.\n\n**Santa Madre Teresa de Calcut\u00e1** \u2014 J\u00e1 religiosa, recebeu um \"chamado dentro do chamado\" para servir os mais pobres dos pobres.\n\nCada voca\u00e7\u00e3o \u00e9 \u00fanica. Deus n\u00e3o se repete.", "scripture": "Ef 2,10 \u2014 Somos obra de Deus, criados em Cristo Jesus para as boas obras que Deus de antem\u00e3o preparou para que nelas and\u00e1ssemos."}'),
('c1c2c3d4-3306-4000-8000-000000000006', 'b1b2c3d4-3333-4000-8000-000000000003', 6, 'Quiz: Discernimento', 'Teste seus conhecimentos', '{"questions": [{"q": "Segundo Santo In\u00e1cio, o que N\u00c3O se deve fazer em tempo de desola\u00e7\u00e3o?", "correct": 1, "options": ["Rezar mais", "Fazer mudan\u00e7as importantes", "Buscar dire\u00e7\u00e3o espiritual", "Jejuar"]}, {"q": "Qual \u00e9 o primeiro passo do discernimento vocacional?", "correct": 1, "options": ["Pesquisar semin\u00e1rios", "Dispor-se a ouvir a vontade de Deus", "Consultar amigos", "Fazer um retiro"]}, {"q": "Quantas voca\u00e7\u00f5es fundamentais a Igreja reconhece?", "correct": 2, "options": ["2", "3", "4", "5"]}]}'),
('d1d2d3d4-4401-4000-8000-000000000001', 'b1b2c3d4-4444-4000-8000-000000000004', 1, 'O Corpo Revela a Pessoa', 'Introdução à Teologia do Corpo', '{"text": "S\u00e3o Jo\u00e3o Paulo II dedicou 129 audi\u00eancias (1979\u20131984) a desenvolver uma vis\u00e3o revolucion\u00e1ria: o corpo humano n\u00e3o \u00e9 apenas mat\u00e9ria \u2014 \u00e9 uma teologia viva, uma linguagem que revela o mist\u00e9rio de Deus.\n\n**\"O corpo, e somente ele, \u00e9 capaz de tornar vis\u00edvel o que \u00e9 invis\u00edvel: o espiritual e o divino.\"** \u2014 S\u00e3o Jo\u00e3o Paulo II\n\nNo relato da cria\u00e7\u00e3o (Gn 1-2), encontramos tr\u00eas experi\u00eancias origin\u00e1rias:\n\n1. **Solid\u00e3o Original** \u2014 Ad\u00e3o percebe que \u00e9 diferente dos animais; possui autoconsci\u00eancia e liberdade.\n2. **Unidade Original** \u2014 \"Ser\u00e3o os dois uma s\u00f3 carne\" (Gn 2,24). O corpo foi feito para a comunh\u00e3o.\n3. **Nudez Original** \u2014 \"Estavam nus e n\u00e3o sentiam vergonha\" (Gn 2,25). A pureza do olhar antes do pecado.\n\nA Teologia do Corpo n\u00e3o \u00e9 apenas sobre sexualidade \u2014 \u00e9 sobre o significado de ser pessoa.", "scripture": "Gn 1,27 \u2014 Deus criou o ser humano \u00e0 sua imagem; \u00e0 imagem de Deus o criou; homem e mulher os criou."}'),
('d1d2d3d4-4402-4000-8000-000000000002', 'b1b2c3d4-4444-4000-8000-000000000004', 2, 'Oração: Contemplar o Dom', 'Agradecer pelo corpo como dom', '{"text": "Senhor Deus,\nV\u00f3s me criastes \u00e0 Vossa imagem e semelhan\u00e7a.\nMeu corpo \u00e9 templo do Esp\u00edrito Santo,\nlinguagem viva do Vosso amor.\n\nAjudai-me a contemplar meu corpo\nn\u00e3o como objeto de vergonha ou idolatria,\nmas como dom sagrado que revela\no mist\u00e9rio da comunh\u00e3o e da entrega.\n\nPurificai meu olhar,\npara que eu veja em cada pessoa\na dignidade inviol\u00e1vel de filho de Deus.\n\nS\u00e3o Jo\u00e3o Paulo II, rogai por n\u00f3s.\nAm\u00e9m.", "instruction": "Reze diante de um crucifixo, contemplando como Cristo entregou Seu corpo por amor."}'),
('d1d2d3d4-4403-4000-8000-000000000003', 'b1b2c3d4-4444-4000-8000-000000000004', 3, 'O Significado Esponsal', 'O corpo como dom e entrega', '{"text": "O conceito central da Teologia do Corpo \u00e9 o **significado esponsal do corpo**: a capacidade de expressar amor como doa\u00e7\u00e3o total de si.\n\n**\"O homem n\u00e3o pode viver sem amor. Ele permanece para si mesmo um ser incompreens\u00edvel se o amor n\u00e3o lhe for revelado.\"** \u2014 Redemptor Hominis, 10\n\nO corpo revela que fomos feitos para:\n- **Dar-nos** \u2014 o amor aut\u00eantico \u00e9 sempre dom de si\n- **Receber** \u2014 aceitar o dom do outro com rever\u00eancia\n- **Ser fecundos** \u2014 o amor gera vida, seja biol\u00f3gica ou espiritual\n\nO pecado original distorceu esta linguagem:\n- A **concupisc\u00eancia** reduz a pessoa a objeto\n- A **vergonha** indica a perda da inoc\u00eancia original\n- O **dom\u00ednio** substitui a comunh\u00e3o\n\nMas Cristo veio restaurar o plano original. Na cruz, Ele mostra o significado esponsal em sua plenitude: entrega total, livre, fiel e fecunda.", "scripture": "Ef 5,25 \u2014 Maridos, amai vossas esposas, como Cristo amou a Igreja e se entregou por ela."}'),
('d1d2d3d4-4404-4000-8000-000000000004', 'b1b2c3d4-4444-4000-8000-000000000004', 4, 'Reflexão: Meu Corpo como Linguagem', 'Integrar corpo e espírito', '{"text": "S\u00e3o Jo\u00e3o Paulo II nos convida a uma revolu\u00e7\u00e3o interior: ver o corpo como linguagem do amor.\n\nReflita:\n1. **Como eu trato meu corpo?** Com respeito ou neglig\u00eancia?\n2. **Como eu olho para o corpo dos outros?** Com rever\u00eancia ou objetifica\u00e7\u00e3o?\n3. **Minha cultura me ajuda ou atrapalha** a viver a verdade do corpo?\n4. **Em que \u00e1reas da minha vida** preciso de purifica\u00e7\u00e3o do olhar?\n5. **Como posso viver a castidade** como afirma\u00e7\u00e3o do amor, n\u00e3o como repress\u00e3o?\n\nA castidade n\u00e3o \u00e9 dizer \"n\u00e3o\" ao corpo \u2014 \u00e9 dizer \"sim\" ao amor verdadeiro.", "prompt": "Escreva sobre como a cultura atual influencia sua vis\u00e3o do corpo e da sexualidade. Como a Teologia do Corpo pode transformar esse olhar?"}'),
('d1d2d3d4-4405-4000-8000-000000000005', 'b1b2c3d4-4444-4000-8000-000000000004', 5, 'A Ressurreição do Corpo', 'Esperança escatológica', '{"text": "A Teologia do Corpo n\u00e3o termina na morte \u2014 aponta para a ressurrei\u00e7\u00e3o.\n\nQuando os saduceus perguntaram a Jesus sobre o casamento na ressurrei\u00e7\u00e3o, Ele respondeu: \"Na ressurrei\u00e7\u00e3o, nem se casam nem se d\u00e3o em casamento, mas s\u00e3o como anjos no c\u00e9u\" (Mt 22,30).\n\nS\u00e3o Jo\u00e3o Paulo II interpreta: na ressurrei\u00e7\u00e3o, o significado esponsal do corpo ser\u00e1 plenamente realizado \u2014 n\u00e3o no matrim\u00f4nio terreno, mas na **comunh\u00e3o perfeita com Deus**.\n\n**O que isso significa para n\u00f3s agora?**\n- O celibato/virgindade consagrada \u00e9 um sinal antecipado da vida futura\n- O matrim\u00f4nio \u00e9 sacramento que aponta para a uni\u00e3o Cristo-Igreja\n- Toda voca\u00e7\u00e3o \u00e9 chamado ao amor que transcende a morte\n\n\"O corpo glorioso ser\u00e1 a revela\u00e7\u00e3o definitiva da beleza de Deus.\"", "scripture": "1Cor 15,44 \u2014 Semeia-se corpo animal, ressuscita corpo espiritual."}'),
('d1d2d3d4-4406-4000-8000-000000000006', 'b1b2c3d4-4444-4000-8000-000000000004', 6, 'Quiz: Teologia do Corpo', 'Teste seus conhecimentos', '{"questions": [{"q": "Quantas audi\u00eancias S\u00e3o Jo\u00e3o Paulo II dedicou \u00e0 Teologia do Corpo?", "correct": 2, "options": ["50", "89", "129", "200"]}, {"q": "Qual \u00e9 o conceito central da Teologia do Corpo?", "correct": 1, "options": ["A proibi\u00e7\u00e3o do prazer", "O significado esponsal do corpo", "A superioridade da alma", "A rejei\u00e7\u00e3o da mat\u00e9ria"]}, {"q": "O que a ''nudez original'' (Gn 2,25) significa teologicamente?", "correct": 1, "options": ["Pobreza material", "Pureza do olhar antes do pecado", "Aus\u00eancia de roupas", "Ingenuidade"]}]}'),
('d96679a4-1535-4692-8929-03959d5fe1c9', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 1, 'O Deserto Interior', NULL, '{"intro": "A m\u00edstica come\u00e7a no sil\u00eancio radical da alma.", "prayer": "Fique 15 minutos em adora\u00e7\u00e3o silenciosa.", "practice": "Desligue as notifica\u00e7\u00f5es do celular por 2 horas.", "reflection": "Onde n\u00e3o h\u00e1 barulho, o Absoluto fala.", "journal_prompt": "Por que voc\u00ea tem medo do sil\u00eancio?"}'),
('7503cfc8-39a8-4c1b-95ba-b98825aa22dd', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 2, 'A Pobreza de Espírito', NULL, '{"intro": "O apego \u00e0s coisas \u00e9 o peso que impede o voo da alma.", "prayer": "Repita: Eu n\u00e3o sou nada, Tu \u00e9s tudo.", "practice": "Doe algo que voc\u00ea gosta para algu\u00e9m que precise.", "reflection": "S\u00f3 quem nada possui pode possuir Tudo.", "journal_prompt": "O que voc\u00ea ainda tenta segurar com as m\u00e3os fechadas?"}'),
('617e9247-45b1-47d6-b787-b309b5b7d02f', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 3, 'A Escuta do Coração', NULL, '{"intro": "A ora\u00e7\u00e3o m\u00edstica \u00e9 mais recep\u00e7\u00e3o do que emiss\u00e3o.", "prayer": "Deixe que Ele fale no centro do seu ser.", "practice": "Passe 10 minutos apenas ouvindo o som ambiente.", "reflection": "N\u00e3o fale, escute. O Mestre est\u00e1 na sala.", "journal_prompt": "Qual foi a \u00faltima coisa que Ele lhe sussurrou?"}'),
('8bb7e628-8e0b-497e-b8f0-dc9cd2f567a9', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 4, 'O Fogo que Consome', NULL, '{"intro": "A purifica\u00e7\u00e3o d\u00f3i, mas \u00e9 ela que nos torna transparentes.", "prayer": "Pe\u00e7a para ser consumido pelo Amor.", "practice": "Agrade\u00e7a por uma dificuldade que te amadureceu.", "reflection": "O amor de Deus n\u00e3o \u00e9 um sentimento, \u00e9 um fogo purificador.", "journal_prompt": "O que em voc\u00ea ainda resiste ao fogo?"}'),
('dfbe9731-29a5-4797-9be6-9b711ac4af1a', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 5, 'A Nuvem do Não-Saber', NULL, '{"intro": "A mente racional tem limites que a f\u00e9 deve ultrapassar.", "prayer": "Confie no escuro da f\u00e9.", "practice": "Abandone hoje o controle sobre uma situa\u00e7\u00e3o incerta.", "reflection": "Para conhec\u00ea-Lo verdadeiramente, \u00e9 preciso desaprender tudo.", "journal_prompt": "Voc\u00ea consegue amar o que n\u00e3o entende?"}'),
('d782d01e-c40c-4e75-80ff-8a3d3467f818', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 6, 'A União Íntima', NULL, '{"intro": "A m\u00edstica \u00e9 o fim da separa\u00e7\u00e3o entre o Criador e a criatura.", "prayer": "Sinta a uni\u00e3o profunda em cada respira\u00e7\u00e3o.", "practice": "Aja hoje como se Ele estivesse fisicamente ao seu lado.", "reflection": "Eu nele e Ele em mim: um s\u00f3 cora\u00e7\u00e3o.", "journal_prompt": "Onde termina voc\u00ea e come\u00e7a Ele?"}'),
('4bae9977-bcbf-4363-8993-5c79976aa325', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 7, 'O Transbordamento no Outro', NULL, '{"intro": "O encontro com Deus deve resultar no encontro com o irm\u00e3o.", "prayer": "Seja o canal por onde o amor dEle flui.", "practice": "Sirva a algu\u00e9m de forma oculta hoje.", "reflection": "A m\u00edstica que n\u00e3o serve n\u00e3o \u00e9 m\u00edstica, \u00e9 ego\u00edsmo.", "journal_prompt": "Como o seu encontro com Deus mudou o seu olhar para o outro?"}'),
('8f3f79a3-bd01-47c3-afe4-172187266e41', 'b2b2b2b2-3030-4000-8000-000000000002', 1, 'Dia 1 — Reconhecer', 'Semana 1: Acolher', '{"pch": "O Senhor est\u00e1 perto dos que t\u00eam o cora\u00e7\u00e3o quebrantado\u2026 Reconhecer a dor \u00e9 o primeiro passo.", "verse": "Sl 34,18", "lectio": "Leia Sl 34,17-22. Deus ouve o grito do justo.", "practice": "Escreva o que d\u00f3i. Sem filtro, sem julgamento.", "question": "Que dor voc\u00ea carrega em sil\u00eancio?"}'),
('7229c52f-8e64-48b4-ad8c-978f30cb3bb9', 'b2b2b2b2-3030-4000-8000-000000000002', 2, 'Dia 2 — Acolher', 'Semana 1: Acolher', '{"pch": "Vinde a mim, todos os cansados\u2026 Voc\u00ea n\u00e3o precisa ser forte o tempo todo.", "verse": "Mt 11,28", "lectio": "Leia Mt 11,25-30. O jugo suave.", "practice": "Permita-se sentir. Chore se precisar. Deus acolhe.", "question": "Quando foi a \u00faltima vez que voc\u00ea se permitiu chorar?"}'),
('228114be-1c58-4279-bd86-90f0aa69b48d', 'b2b2b2b2-3030-4000-8000-000000000002', 3, 'Dia 3 — Nomear', 'Semana 1: Acolher', '{"pch": "Onde est\u00e1s? Deus pergunta n\u00e3o porque n\u00e3o sabe\u2026 mas porque voc\u00ea precisa responder.", "verse": "Gn 3,9", "lectio": "Leia Gn 3,8-13. Ad\u00e3o se escondeu. Deus o buscou.", "practice": "Nomeie 3 emo\u00e7\u00f5es que voc\u00ea sente agora. Sem julg\u00e1-las.", "question": "Se sua dor tivesse um nome, qual seria?"}'),
('8d54eebc-3e64-4de2-b654-e644df39afdf', 'b2b2b2b2-3030-4000-8000-000000000002', 4, 'Dia 4 — Chorar', 'Semana 1: Acolher', '{"pch": "Jesus chorou. Se Deus chora, por que voc\u00ea n\u00e3o pode?", "verse": "Jo 11,35", "lectio": "Leia Jo 11,32-44. Jesus se comoveu antes de agir.", "practice": "Leia um salmo de lamento (Sl 42). Fa\u00e7a dele sua ora\u00e7\u00e3o.", "question": "Que l\u00e1grimas voc\u00ea segurou por tempo demais?"}'),
('533c65e5-95e8-4e3d-a3ef-9519036e8743', 'b2b2b2b2-3030-4000-8000-000000000002', 5, 'Dia 5 — Abandono', 'Semana 1: Acolher', '{"pch": "Ainda que meu pai e minha m\u00e3e me abandonem\u2026 o Senhor me acolher\u00e1.", "verse": "Sl 27,10", "lectio": "Leia Sl 27. Deus \u00e9 luz e salva\u00e7\u00e3o.", "practice": "Escreva uma carta ao seu eu crian\u00e7a. Diga o que ele precisava ouvir.", "question": "Quem te fez sentir abandonado?"}'),
('cf838250-8259-4ee5-8181-cc2b15a71541', 'b2b2b2b2-3030-4000-8000-000000000002', 6, 'Dia 6 — Rejeição', 'Semana 1: Acolher', '{"pch": "Desprezado e rejeitado\u2026 Jesus conhece a rejei\u00e7\u00e3o. Ele entende.", "verse": "Is 53,3", "lectio": "Leia Is 53,1-6. O servo sofredor.", "practice": "Identifique padr\u00f5es de rejei\u00e7\u00e3o na sua vida. Ore sobre cada um.", "question": "Que rejei\u00e7\u00e3o ainda ecoa dentro de voc\u00ea?"}'),
('3aef49a3-97c8-4f50-9fef-dfe888deb99d', 'b2b2b2b2-3030-4000-8000-000000000002', 7, 'Dia 7 — Descanso', 'Semana 1: Acolher', '{"pch": "Ele me faz repousar em pastos verdejantes\u2026 A cura come\u00e7a no descanso, n\u00e3o no esfor\u00e7o.", "verse": "Sl 23,2", "lectio": "Leia Sl 23. O Bom Pastor cuida.", "practice": "Tire 30 minutos hoje sem produtividade. Apenas seja.", "question": "Voc\u00ea tem descansado de verdade?"}'),
('ee9c9fe0-4f4b-4ccc-aceb-150a0ac29e43', 'b2b2b2b2-3030-4000-8000-000000000002', 8, 'Dia 8 — Raiva', 'Semana 2: Processar', '{"pch": "Irai-vos e n\u00e3o pequeis\u2026 A raiva n\u00e3o \u00e9 pecado. O que voc\u00ea faz com ela pode ser.", "verse": "Ef 4,26", "lectio": "Leia Ef 4,25-32. Falar a verdade em amor.", "practice": "Escreva uma carta de raiva (sem enviar). Depois, entregue a Deus.", "question": "De que voc\u00ea tem raiva e nunca admitiu?"}'),
('b46a74c9-a461-4059-bf94-083845914f4f', 'b2b2b2b2-3030-4000-8000-000000000002', 9, 'Dia 9 — Culpa', 'Semana 2: Processar', '{"pch": "Nenhuma condena\u00e7\u00e3o h\u00e1\u2026 para os que est\u00e3o em Cristo. A culpa que condena n\u00e3o vem de Deus.", "verse": "Rm 8,1", "lectio": "Leia Rm 8,1-4. Liberdade da condena\u00e7\u00e3o.", "practice": "Diga em voz alta: Eu sou perdoado. Eu estou livre.", "question": "Que culpa te persegue mesmo depois de ter sido perdoado?"}'),
('e85b59ed-a6af-4ddf-becc-eaea5b5d0400', 'b2b2b2b2-3030-4000-8000-000000000002', 10, 'Dia 10 — Vergonha', 'Semana 2: Processar', '{"pch": "Em vez da vergonha, por\u00e7\u00e3o dobrada\u2026 Deus troca sua vergonha por honra.", "verse": "Is 61,7", "lectio": "Leia Is 61,1-7. O Esp\u00edrito do Senhor cura.", "practice": "Compartilhe com Deus (em ora\u00e7\u00e3o) aquilo que esconde de todos.", "question": "De que voc\u00ea tem vergonha que nunca contou?"}'),
('c18e4986-5cf4-45f0-8643-bad413671530', 'b2b2b2b2-3030-4000-8000-000000000002', 11, 'Dia 11 — Luto', 'Semana 2: Processar', '{"pch": "Enxugar\u00e1 toda l\u00e1grima\u2026 A dor \u00e9 tempor\u00e1ria. A consola\u00e7\u00e3o \u00e9 eterna.", "verse": "Ap 21,4", "lectio": "Leia Ap 21,1-5. O novo c\u00e9u e a nova terra.", "practice": "Escreva uma despedida para o que perdeu. Permita-se sentir.", "question": "Que perda voc\u00ea ainda n\u00e3o processou?"}'),
('bc9b38b5-7633-4e61-a5aa-d6b58133c738', 'b2b2b2b2-3030-4000-8000-000000000002', 12, 'Dia 12 — Medo', 'Semana 2: Processar', '{"pch": "Deus n\u00e3o nos deu esp\u00edrito de medo\u2026 mas de poder, amor e equil\u00edbrio.", "verse": "2Tm 1,7", "lectio": "Leia 2Tm 1,6-12. Reavivar o dom de Deus.", "practice": "Enfrente um pequeno medo hoje. Celebre a vit\u00f3ria.", "question": "Que medo controla sua vida sem voc\u00ea perceber?"}'),
('43edf712-d630-4462-b3d2-8cb62fa8aa8e', 'b2b2b2b2-3030-4000-8000-000000000002', 13, 'Dia 13 — Perdoar-se', 'Semana 2: Processar', '{"pch": "Se confessarmos os nossos pecados, Ele \u00e9 fiel e justo para nos perdoar\u2026 Voc\u00ea tamb\u00e9m pode se perdoar.", "verse": "1Jo 1,9", "lectio": "Leia 1Jo 1,5-10. Andar na luz.", "practice": "Olhe no espelho e diga: Eu te perdoo. Eu te amo.", "question": "O que voc\u00ea fez que ainda n\u00e3o se perdoou?"}'),
('27d85dd7-a74c-4d01-8e0a-e90bdbbf424e', 'b2b2b2b2-3030-4000-8000-000000000002', 14, 'Dia 14 — Perdoar outros', 'Semana 2: Processar', '{"pch": "Se perdoardes\u2026 tamb\u00e9m o Pai vos perdoar\u00e1. Perdoar n\u00e3o \u00e9 esquecer \u2014 \u00e9 soltar.", "verse": "Mt 6,14", "lectio": "Leia Mt 6,12-15 e Mt 18,21-35. O servo impiedoso.", "practice": "Reze pelo nome de quem te machucou. Solte a amarra.", "question": "Quem ainda ocupa espa\u00e7o na sua dor?"}'),
('404a407c-7d20-40d5-9662-2a11188d2e77', 'b2b2b2b2-3030-4000-8000-000000000002', 15, 'Dia 15 — Nova pele', 'Semana 3: Reconstruir', '{"pch": "Eis que farei entrar em v\u00f3s o esp\u00edrito, e vivereis\u2026 Ossos secos podem viver.", "verse": "Ez 37,5", "lectio": "Leia Ez 37,1-14. O vale dos ossos secos.", "practice": "Visualize sua vida restaurada. Escreva como seria.", "question": "Que parte de voc\u00ea precisa renascer?"}'),
('18727147-0b1d-463f-a650-d85e3000493d', 'b2b2b2b2-3030-4000-8000-000000000002', 16, 'Dia 16 — Autocompaixão', 'Semana 3: Reconstruir', '{"pch": "Como um pai se compadece dos filhos\u2026 Seja gentil consigo mesmo como Deus \u00e9 com voc\u00ea.", "verse": "Sl 103,13", "lectio": "Leia Sl 103,8-14. Deus conhece nossa fragilidade.", "practice": "Hoje, trate-se como trataria seu melhor amigo.", "question": "Como voc\u00ea se trata quando falha?"}'),
('247ec458-de31-4b8d-a22c-15f26a0969e7', 'b2b2b2b2-3030-4000-8000-000000000002', 17, 'Dia 17 — Limites', 'Semana 3: Reconstruir', '{"pch": "Seja o vosso sim, sim; e o vosso n\u00e3o, n\u00e3o\u2026 Limites saud\u00e1veis protegem o que Deus cura.", "verse": "Mt 5,37", "lectio": "Leia Mt 5,33-37. Clareza nas palavras.", "practice": "Defina 1 limite que voc\u00ea vai estabelecer esta semana.", "question": "Onde voc\u00ea precisa dizer n\u00e3o para proteger sua paz?"}'),
('78f04225-0188-4a5f-9641-566f2ca54937', 'b2b2b2b2-3030-4000-8000-000000000002', 18, 'Dia 18 — Gratidão', 'Semana 3: Reconstruir', '{"pch": "Transformaste o meu pranto em dan\u00e7a\u2026 A gratid\u00e3o muda o foco da dor para a gra\u00e7a.", "verse": "Sl 30,11", "lectio": "Leia Sl 30. De lamento a louvor.", "practice": "Escreva 5 coisas boas que existem por causa de algo dif\u00edcil.", "question": "O que de bom nasceu de algo que te machucou?"}'),
('e13ea0a4-693c-4ed8-87d4-f83b33fbcc98', 'b2b2b2b2-3030-4000-8000-000000000002', 19, 'Dia 19 — Força', 'Semana 3: Reconstruir', '{"pch": "Os que esperam no Senhor renovar\u00e3o as suas for\u00e7as\u2026 A for\u00e7a vem da espera, n\u00e3o da pressa.", "verse": "Is 40,31", "lectio": "Leia Is 40,28-31. O Deus eterno n\u00e3o se cansa.", "practice": "Fa\u00e7a algo que recarregue sua energia emocional hoje.", "question": "De onde voc\u00ea tira for\u00e7a quando tudo parece demais?"}'),
('f8455191-ac40-4c0c-bec1-b628b7d118f1', 'b2b2b2b2-3030-4000-8000-000000000002', 20, 'Dia 20 — Vulnerabilidade', 'Semana 3: Reconstruir', '{"pch": "Temos esse tesouro em vasos de barro\u2026 Sua fragilidade n\u00e3o \u00e9 fraqueza \u2014 \u00e9 transpar\u00eancia.", "verse": "2Cor 4,7", "lectio": "Leia 2Cor 4,7-12. Poder na fragilidade.", "practice": "Compartilhe algo verdadeiro com algu\u00e9m de confian\u00e7a.", "question": "Com quem voc\u00ea pode ser vulner\u00e1vel?"}'),
('be9d5286-0a3e-4dbf-aa8d-f41237d8df95', 'b2b2b2b2-3030-4000-8000-000000000002', 21, 'Dia 21 — Esperança', 'Semana 3: Reconstruir', '{"pch": "O Deus da esperan\u00e7a vos encha de alegria e paz\u2026 A esperan\u00e7a \u00e9 uma pessoa, n\u00e3o um sentimento.", "verse": "Rm 15,13", "lectio": "Leia Rm 15,13. Transbordar de esperan\u00e7a.", "practice": "Escreva 3 coisas que ainda espera ver acontecer.", "question": "Em que voc\u00ea ainda espera?"}'),
('58a2a723-a8a3-44cf-9acb-7d799ed70a2d', 'b2b2b2b2-3030-4000-8000-000000000002', 22, 'Dia 22 — Recomeço', 'Semana 4: Integrar', '{"pch": "As miseric\u00f3rdias do Senhor renovam-se cada manh\u00e3\u2026 Cada dia \u00e9 um novo come\u00e7o.", "verse": "Lm 3,22-23", "lectio": "Leia Lm 3,19-26. Esperan\u00e7a no meio da ru\u00edna.", "practice": "Comece algo novo hoje \u2014 mesmo pequeno.", "question": "O que voc\u00ea gostaria de recome\u00e7ar?"}'),
('c20d1e17-3623-4448-99a6-1c8146565526', 'b2b2b2b2-3030-4000-8000-000000000002', 23, 'Dia 23 — Identidade restaurada', 'Semana 4: Integrar', '{"pch": "Eu te chamei pelo teu nome, tu \u00e9s meu\u2026 Sua identidade n\u00e3o est\u00e1 na dor \u2014 est\u00e1 em quem te criou.", "verse": "Is 43,1", "lectio": "Leia Is 43,1-7. Precioso aos olhos de Deus.", "practice": "Escreva: Eu sou mais do que aconteceu comigo porque _____", "question": "Como voc\u00ea se define al\u00e9m da sua dor?"}'),
('79b7e0cb-da66-4450-8acc-fc19c16c5348', 'b2b2b2b2-3030-4000-8000-000000000002', 24, 'Dia 24 — Propósito na dor', 'Semana 4: Integrar', '{"pch": "Todas as coisas cooperam para o bem\u2026 Sua dor tem prop\u00f3sito, mesmo quando n\u00e3o parece.", "verse": "Rm 8,28", "lectio": "Leia Rm 8,28-30. O plano de Deus.", "practice": "Escreva como sua dor pode servir a outra pessoa.", "question": "Que sentido voc\u00ea encontra na sua hist\u00f3ria?"}'),
('6352aa56-67fc-470f-a23a-9bf0366b1caf', 'b2b2b2b2-3030-4000-8000-000000000002', 25, 'Dia 25 — Cicatrizes', 'Semana 4: Integrar', '{"pch": "Jesus mostrou suas cicatrizes\u2026 Elas n\u00e3o desapareceram \u2014 se tornaram testemunho.", "verse": "Jo 20,27", "lectio": "Leia Jo 20,24-29. Tom\u00e9 tocou as feridas.", "practice": "Agrade\u00e7a por uma cicatriz. Ela prova que voc\u00ea sobreviveu.", "question": "Que cicatrizes suas contam uma hist\u00f3ria de supera\u00e7\u00e3o?"}'),
('d74e36fd-1550-42bf-a471-75f292b882a0', 'b2b2b2b2-3030-4000-8000-000000000002', 26, 'Dia 26 — Alegria', 'Semana 4: Integrar', '{"pch": "A alegria do Senhor \u00e9 a vossa for\u00e7a\u2026 A alegria n\u00e3o nega a dor \u2014 coexiste com ela.", "verse": "Ne 8,10", "lectio": "Leia Ne 8,9-12. Chorar e celebrar no mesmo dia.", "practice": "Fa\u00e7a algo que te d\u00ea alegria pura hoje.", "question": "O que te d\u00e1 alegria verdadeira?"}'),
('78ece41c-115b-42c7-b9ab-f4e888bd44c3', 'b2b2b2b2-3030-4000-8000-000000000002', 27, 'Dia 27 — Conexão', 'Semana 4: Integrar', '{"pch": "Levai as cargas uns dos outros\u2026 Cura n\u00e3o acontece no isolamento.", "verse": "Gl 6,2", "lectio": "Leia Gl 6,1-5. Comunidade na restaura\u00e7\u00e3o.", "practice": "Ligue para algu\u00e9m. Diga: preciso de voc\u00ea.", "question": "Quem voc\u00ea precisa ao seu lado neste momento?"}'),
('514f473e-a51b-4076-b0de-75285f981850', 'b2b2b2b2-3030-4000-8000-000000000002', 28, 'Dia 28 — Paz', 'Semana 4: Integrar', '{"pch": "A minha paz vos dou\u2026 n\u00e3o como o mundo a d\u00e1. Paz n\u00e3o \u00e9 aus\u00eancia de conflito \u2014 \u00e9 presen\u00e7a de Deus.", "verse": "Jo 14,27", "lectio": "Leia Jo 14,25-31. O Consolador vem.", "practice": "Identifique o ladr\u00e3o de paz. Entregue-o em ora\u00e7\u00e3o.", "question": "O que te rouba a paz?"}'),
('275c740d-e9b2-456f-84d3-7e2d2e764762', 'b2b2b2b2-3030-4000-8000-000000000002', 29, 'Dia 29 — Testemunho', 'Semana 4: Integrar', '{"pch": "Tirou-me do po\u00e7o\u2026 e p\u00f4s nos meus l\u00e1bios um c\u00e2ntico novo. Sua hist\u00f3ria \u00e9 seu testemunho.", "verse": "Sl 40,2-3", "lectio": "Leia Sl 40,1-5. Da espera ao louvor.", "practice": "Escreva seu testemunho em 5 frases.", "question": "O que voc\u00ea diria a algu\u00e9m que est\u00e1 onde voc\u00ea estava?"}'),
('a80d565d-c6d9-4f86-b941-cec6e83d1841', 'b2b2b2b2-3030-4000-8000-000000000002', 30, 'Dia 30 — Inteiro', 'Semana 4: Integrar', '{"pch": "Sara os quebrantados de cora\u00e7\u00e3o\u2026 e liga-lhes as feridas. Voc\u00ea n\u00e3o est\u00e1 quebrado. Est\u00e1 sendo restaurado.", "verse": "Sl 147,3", "lectio": "Leia Sl 147,1-7. Deus conta as estrelas e sara os cora\u00e7\u00f5es.", "practice": "Releia suas reflex\u00f5es dos 30 dias. Escreva uma carta de gratid\u00e3o a si mesmo.", "question": "Quem voc\u00ea se tornou atrav\u00e9s da dor?"}'),
('f75b8079-8b74-4a7d-b250-c3e7b88ced2b', 'c1c2c3d4-3030-4000-8000-000000000030', 1, 'Perceber', 'Semana 1 — Despertar', '{"pch": "A pressa revela\u2026 onde a confian\u00e7a ainda n\u00e3o chegou.", "verse": "Mt 6,25-34", "lectio": "Leia o texto lentamente. Pare na palavra que incomoda. Pergunte: por que essa palavra me toca?", "practice": "Escreva no di\u00e1rio: qual \u00e1rea da minha vida estou tentando controlar com pressa?", "question": "O que est\u00e1 te acelerando?"}'),
('986ec036-538c-4d29-9ce3-d78185c46588', 'c1c2c3d4-3030-4000-8000-000000000030', 2, 'Pausar', 'Semana 1 — Despertar', '{"pch": "Nem todo movimento \u00e9 progresso\u2026 \u00e0s vezes \u00e9 fuga.", "verse": "Sl 46,10", "lectio": "Sente-se em sil\u00eancio por 3 minutos antes de ler. Depois leia o salmo duas vezes.", "practice": "Identifique uma a\u00e7\u00e3o que voc\u00ea repete por ansiedade, n\u00e3o por necessidade.", "question": "Do que voc\u00ea est\u00e1 fugindo?"}'),
('8040b3ca-8cce-4c4e-8e65-840a0d18de35', 'c1c2c3d4-3030-4000-8000-000000000030', 3, 'Sentir', 'Semana 1 — Despertar', '{"pch": "Sentir n\u00e3o \u00e9 fraqueza\u2026 \u00e9 acesso.", "verse": "Sl 34,18", "lectio": "Leia o vers\u00edculo e pergunte: onde est\u00e1 essa dor em mim agora?", "practice": "Nomeie tr\u00eas emo\u00e7\u00f5es que voc\u00ea sentiu hoje, sem julgamento.", "question": "O que voc\u00ea evita sentir?"}'),
('77fca868-67b4-4f17-91cd-c74cb2546161', 'c1c2c3d4-3030-4000-8000-000000000030', 4, 'Nomear', 'Semana 1 — Despertar', '{"pch": "Aquilo que voc\u00ea n\u00e3o nomeia\u2026 te controla.", "verse": "Gn 2,19-20", "lectio": "Assim como Ad\u00e3o nomeou cada criatura, nomeie o que vive dentro de voc\u00ea.", "practice": "Escreva: qual medo, h\u00e1bito ou ferida eu ainda n\u00e3o nomeei?", "question": "O que voc\u00ea ainda n\u00e3o enfrentou?"}'),
('45d795f0-f382-43ac-9a04-101bbbbd2a76', 'c1c2c3d4-3030-4000-8000-000000000030', 5, 'Aceitar', 'Semana 1 — Despertar', '{"pch": "Aceitar n\u00e3o \u00e9 desistir\u2026 \u00e9 parar de lutar contra o que j\u00e1 \u00e9.", "verse": "Rm 8,28", "lectio": "Leia e pergunte: o que Deus pode estar fazendo com aquilo que eu rejeito?", "practice": "Escreva uma coisa que voc\u00ea precisa parar de resistir.", "question": "O que voc\u00ea resiste?"}'),
('50f1689c-f250-4f15-870a-89b443a270d5', 'c1c2c3d4-3030-4000-8000-000000000030', 6, 'Silenciar', 'Semana 1 — Despertar', '{"pch": "No sil\u00eancio\u2026 a verdade sobe.", "verse": "1Rs 19,11-13", "lectio": "Fique 5 minutos em sil\u00eancio antes de ler. O que surgiu?", "practice": "Reserve 10 minutos de sil\u00eancio completo hoje.", "question": "O que aparece quando voc\u00ea para?"}'),
('0288ddc5-3827-4163-be3a-5e8e4458e3bb', 'c1c2c3d4-3030-4000-8000-000000000030', 7, 'Observar', 'Semana 1 — Despertar', '{"pch": "Voc\u00ea n\u00e3o \u00e9 o pensamento\u2026 \u00e9 quem percebe.", "verse": "Lc 12,22-26", "lectio": "Leia e observe: quais pensamentos autom\u00e1ticos governam suas decis\u00f5es?", "practice": "Anote 3 pensamentos recorrentes que podem ser cren\u00e7as, n\u00e3o verdades.", "question": "O que voc\u00ea est\u00e1 acreditando sem questionar?"}'),
('b012f24c-4a6b-4fbb-9076-34f2909d1246', 'c1c2c3d4-3030-4000-8000-000000000030', 8, 'Soltar Controle', 'Semana 2 — Desconstruir', '{"pch": "Controlar \u00e9 a forma mais elegante de desconfiar.", "verse": "Pv 3,5-6", "lectio": "Leia e pergunte: em que \u00e1rea eu confio mais em mim do que em Deus?", "practice": "Escolha uma coisa para n\u00e3o controlar hoje. Observe o que sente.", "question": "O que voc\u00ea n\u00e3o consegue largar?"}'),
('ab2806d7-2b4c-43b2-a7e4-c491681c8b11', 'c1c2c3d4-3030-4000-8000-000000000030', 9, 'Enfrentar Medo', 'Semana 2 — Desconstruir', '{"pch": "O medo n\u00e3o \u00e9 sinal de fraqueza\u2026 \u00e9 sinal de fronteira.", "verse": "Is 41,10", "lectio": "Leia a promessa. Pergunte: qual medo Deus est\u00e1 me convidando a atravessar?", "practice": "Nomeie seu maior medo atual e escreva o que aconteceria se ele n\u00e3o existisse.", "question": "Qual medo te paralisa?"}'),
('c6550de4-ada8-4202-b793-7b28ad948975', 'c1c2c3d4-3030-4000-8000-000000000030', 10, 'Identificar Padrões', 'Semana 2 — Desconstruir', '{"pch": "Voc\u00ea chama de personalidade\u2026 mas pode ser repeti\u00e7\u00e3o.", "verse": "Rm 7,15-20", "lectio": "Paulo descreve a luta interior. Qual luta \u00e9 sua?", "practice": "Identifique um padr\u00e3o que se repete em relacionamentos, trabalho ou emo\u00e7\u00f5es.", "question": "Qual padr\u00e3o voc\u00ea repete sem perceber?"}'),
('698dfc1a-e44e-42d0-b4fe-66fc6f0cdc37', 'c1c2c3d4-3030-4000-8000-000000000030', 11, 'Romper Crenças', 'Semana 2 — Desconstruir', '{"pch": "A verdade liberta\u2026 mas primeiro incomoda.", "verse": "Jo 8,32", "lectio": "Leia e pergunte: qual mentira eu acreditei sobre mim?", "practice": "Escreva uma cren\u00e7a limitante e reescreva-a \u00e0 luz da Palavra.", "question": "Qual cren\u00e7a sobre voc\u00ea mesmo precisa ser revisada?"}'),
('4affb73b-d4d7-4845-b7cc-a5c1f89739a5', 'c1c2c3d4-3030-4000-8000-000000000030', 12, 'Perdoar', 'Semana 2 — Desconstruir', '{"pch": "Perdoar n\u00e3o \u00e9 esquecer\u2026 \u00e9 soltar a corda que te prende ao outro.", "verse": "Mt 6,14-15", "lectio": "Leia e sinta: qual peso do passado voc\u00ea ainda carrega?", "practice": "Escreva uma carta de perd\u00e3o \u2014 n\u00e3o precisa enviar.", "question": "Quem voc\u00ea ainda n\u00e3o perdoou?"}'),
('3a39399b-5772-45fb-b820-48aff4098714', 'c1c2c3d4-3030-4000-8000-000000000030', 13, 'Liberar Peso', 'Semana 2 — Desconstruir', '{"pch": "Carregar demais n\u00e3o \u00e9 for\u00e7a\u2026 \u00e9 desconfian\u00e7a.", "verse": "Mt 11,28-30", "lectio": "Jesus convida ao descanso. O que voc\u00ea precisa entregar?", "practice": "Fa\u00e7a uma lista do que pesa e marque o que n\u00e3o depende de voc\u00ea.", "question": "O que pesa em voc\u00ea que n\u00e3o \u00e9 seu para carregar?"}'),
('272da72e-2655-4fb8-852c-23383d4f8a62', 'c1c2c3d4-3030-4000-8000-000000000030', 14, 'Desapegar', 'Semana 2 — Desconstruir', '{"pch": "Enquanto voc\u00ea olha para tr\u00e1s\u2026 n\u00e3o enxerga o que est\u00e1 \u00e0 frente.", "verse": "Fl 3,13-14", "lectio": "Paulo esquece o que ficou para tr\u00e1s. O que voc\u00ea precisa deixar?", "practice": "Escolha uma mem\u00f3ria, h\u00e1bito ou v\u00ednculo para soltar hoje.", "question": "O que do passado ainda te define?"}'),
('86d859f0-cfea-4b42-a4b5-b15ae072728b', 'c1c2c3d4-3030-4000-8000-000000000030', 15, 'Nova Visão', 'Semana 3 — Reconstruir', '{"pch": "Voc\u00ea n\u00e3o precisa de uma nova chance\u2026 precisa de novos olhos.", "verse": "2Cor 5,17", "lectio": "Leia e pergunte: o que significa ser nova criatura para mim hoje?", "practice": "Escreva como seria seu dia se voc\u00ea acreditasse plenamente nisso.", "question": "O que mudaria se voc\u00ea se visse como Deus te v\u00ea?"}'),
('c155855b-95d5-4fb8-9cd7-68739b6b56f2', 'c1c2c3d4-3030-4000-8000-000000000030', 16, 'Escolhas', 'Semana 3 — Reconstruir', '{"pch": "Toda manh\u00e3 voc\u00ea escolhe\u2026 mesmo quando acha que n\u00e3o.", "verse": "Dt 30,19", "lectio": "Deus coloca vida e morte diante de n\u00f3s. O que voc\u00ea escolhe hoje?", "practice": "Tome uma micro-decis\u00e3o que voc\u00ea adia h\u00e1 dias.", "question": "Qual escolha voc\u00ea tem evitado?"}'),
('022cabd4-752c-4df8-8e91-9e8fe44cdca1', 'c1c2c3d4-3030-4000-8000-000000000030', 17, 'Hábitos', 'Semana 3 — Reconstruir', '{"pch": "Disciplina n\u00e3o \u00e9 castigo\u2026 \u00e9 cuidado com quem voc\u00ea est\u00e1 se tornando.", "verse": "1Cor 9,27", "lectio": "Paulo disciplina o corpo. Qual \u00e1rea da sua vida precisa de ordem?", "practice": "Defina um micro-h\u00e1bito para os pr\u00f3ximos 7 dias.", "question": "Qual h\u00e1bito te aproxima de quem voc\u00ea quer ser?"}'),
('d9150e85-aa75-4b79-8feb-ceeeb96760a3', 'c1c2c3d4-3030-4000-8000-000000000030', 18, 'Disciplina', 'Semana 3 — Reconstruir', '{"pch": "O que d\u00f3i agora\u2026 forma depois.", "verse": "Hb 12,11", "lectio": "A disciplina parece dolorosa, mas gera fruto. Qual fruto voc\u00ea busca?", "practice": "Pratique algo dif\u00edcil por 15 minutos hoje, conscientemente.", "question": "Qual disciplina voc\u00ea resiste mas sabe que precisa?"}'),
('459230b6-a949-4e59-96cd-1e04dfdb96c3', 'c1c2c3d4-3030-4000-8000-000000000030', 19, 'Foco', 'Semana 3 — Reconstruir', '{"pch": "Foco n\u00e3o \u00e9 ignorar o resto\u2026 \u00e9 saber o que importa agora.", "verse": "Fl 3,13-14", "lectio": "Paulo avan\u00e7a para o alvo. Qual \u00e9 o seu alvo neste momento?", "practice": "Elimine uma distra\u00e7\u00e3o por 24 horas.", "question": "O que merece sua aten\u00e7\u00e3o total hoje?"}'),
('7b5634a6-a6a0-43c7-8919-77729705818a', 'c1c2c3d4-3030-4000-8000-000000000030', 20, 'Constância', 'Semana 3 — Reconstruir', '{"pch": "Desistir \u00e9 f\u00e1cil\u2026 mas o fruto vem pra quem fica.", "verse": "Gl 6,9", "lectio": "N\u00e3o se canse de fazer o bem. Em que \u00e1rea voc\u00ea cansa r\u00e1pido?", "practice": "Recomece algo que voc\u00ea abandonou esta semana.", "question": "Onde voc\u00ea tem desistido cedo demais?"}'),
('4281821b-5b55-4965-b5c5-4c01130eec6a', 'c1c2c3d4-3030-4000-8000-000000000030', 21, 'Identidade', 'Semana 3 — Reconstruir', '{"pch": "Voc\u00ea n\u00e3o \u00e9 o que fez\u2026 \u00e9 o que foi feito para ser.", "verse": "Ef 2,10", "lectio": "Somos obra de Deus. O que isso muda na forma como voc\u00ea se v\u00ea?", "practice": "Escreva: quem eu sou, sem t\u00edtulos, sem pap\u00e9is, sem m\u00e1scaras.", "question": "Quem voc\u00ea \u00e9 quando ningu\u00e9m est\u00e1 olhando?"}'),
('5dd229da-b343-49b7-9c7a-f79db3faf550', 'c1c2c3d4-3030-4000-8000-000000000030', 22, 'Presença', 'Semana 4 — Integrar', '{"pch": "Deus n\u00e3o est\u00e1 no destino\u2026 est\u00e1 no caminho.", "verse": "Sl 139,7-10", "lectio": "Leia e pergunte: em que momento do meu dia Deus esteve mais perto?", "practice": "Viva uma hora inteira com aten\u00e7\u00e3o plena ao presente.", "question": "Onde voc\u00ea sente a presen\u00e7a de Deus hoje?"}'),
('e1445250-0515-4257-8395-5e40727cc79b', 'c1c2c3d4-3030-4000-8000-000000000030', 23, 'Propósito', 'Semana 4 — Integrar', '{"pch": "Voc\u00ea n\u00e3o precisa inventar um prop\u00f3sito\u2026 precisa descobrir o que j\u00e1 foi plantado.", "verse": "Jr 29,11", "lectio": "Deus tem planos de paz. O que ressoa dentro de voc\u00ea ao ler isso?", "practice": "Liste 3 coisas que te d\u00e3o energia e alegria verdadeira.", "question": "O que te faz sentir vivo?"}'),
('d58e1b64-b4b6-4bd7-ae8a-9175a9b03814', 'c1c2c3d4-3030-4000-8000-000000000030', 24, 'Confiança', 'Semana 4 — Integrar', '{"pch": "Confiar n\u00e3o \u00e9 entender\u2026 \u00e9 caminhar mesmo sem ver.", "verse": "Sl 37,5", "lectio": "Entregue o seu caminho ao Senhor. O que voc\u00ea ainda segura?", "practice": "Entregue uma preocupa\u00e7\u00e3o em ora\u00e7\u00e3o e n\u00e3o a retome hoje.", "question": "Em que \u00e1rea da vida voc\u00ea precisa confiar mais?"}'),
('0363689a-20b6-44e4-ab42-70ef3e29a688', 'c1c2c3d4-3030-4000-8000-000000000030', 25, 'Entrega', 'Semana 4 — Integrar', '{"pch": "A maior liberdade\u2026 \u00e9 querer o que Deus quer.", "verse": "Lc 22,42", "lectio": "Jesus no Gets\u00eamani: n\u00e3o a minha, mas a Tua vontade. O que isso significa pra voc\u00ea?", "practice": "Fa\u00e7a uma ora\u00e7\u00e3o de entrega: escreva o que voc\u00ea entrega hoje.", "question": "O que voc\u00ea ainda n\u00e3o entregou?"}'),
('3f5434e3-ec6b-44b7-870b-47004ab1632f', 'c1c2c3d4-3030-4000-8000-000000000030', 26, 'Paz', 'Semana 4 — Integrar', '{"pch": "A paz de Cristo n\u00e3o \u00e9 aus\u00eancia de luta\u2026 \u00e9 presen\u00e7a em meio a ela.", "verse": "Jo 14,27", "lectio": "Leia e pergunte: a paz que eu busco \u00e9 do mundo ou de Deus?", "practice": "Identifique uma fonte de agita\u00e7\u00e3o e entregue-a em sil\u00eancio.", "question": "O que rouba sua paz?"}'),
('e576064d-c53e-44c8-8997-eb90d6527d84', 'c1c2c3d4-3030-4000-8000-000000000030', 27, 'Direção', 'Semana 4 — Integrar', '{"pch": "Voc\u00ea n\u00e3o precisa ver todo o caminho\u2026 s\u00f3 o pr\u00f3ximo passo.", "verse": "Sl 119,105", "lectio": "A Palavra \u00e9 l\u00e2mpada. Que luz ela traz para sua decis\u00e3o de hoje?", "practice": "Tome uma decis\u00e3o que voc\u00ea adia, confiando na luz que j\u00e1 tem.", "question": "Qual \u00e9 o pr\u00f3ximo passo que voc\u00ea j\u00e1 sabe?"}'),
('a0445828-d326-4697-9786-60b513aaba02', 'c1c2c3d4-3030-4000-8000-000000000030', 28, 'Compromisso', 'Semana 4 — Integrar', '{"pch": "Decidir \u00e9 cortar todas as outras op\u00e7\u00f5es\u2026 e caminhar.", "verse": "Js 24,15", "lectio": "Josu\u00e9 escolhe servir ao Senhor. Qual \u00e9 a sua escolha hoje?", "practice": "Escreva um compromisso concreto para os pr\u00f3ximos 30 dias.", "question": "Com o que voc\u00ea se compromete a partir de agora?"}'),
('013d164a-ae98-43c4-9957-2211f898021e', 'c1c2c3d4-3030-4000-8000-000000000030', 29, 'Consolidação', 'Semana 4 — Integrar', '{"pch": "Ouvir sem fazer\u2026 \u00e9 o sono da alma.", "verse": "Tg 1,22-25", "lectio": "Seja praticante da Palavra. Qual ensinamento desta jornada precisa virar a\u00e7\u00e3o?", "practice": "Releia suas reflex\u00f5es da semana 1. O que mudou?", "question": "O que voc\u00ea aprendeu mas ainda n\u00e3o praticou?"}'),
('5529aca4-697e-4176-af9d-096c5a60c73f', 'c1c2c3d4-3030-4000-8000-000000000030', 30, 'Novo Começo', 'Semana 4 — Integrar', '{"pch": "Voc\u00ea n\u00e3o chegou ao fim\u2026 voc\u00ea saiu de onde estava.", "verse": "Ap 21,5", "lectio": "Eu fa\u00e7o novas todas as coisas. O que \u00e9 novo em voc\u00ea agora?", "practice": "Escreva uma carta para si mesmo: quem eu era no dia 1, quem eu sou no dia 30, e para onde vou.", "question": "Quem voc\u00ea se tornou?"}'),
('2711a145-076a-4092-99b4-9a1f1992ae2b', 'c3c3c3c3-3030-4000-8000-000000000003', 1, 'Dia 1 — Ruído', 'Semana 1: Parar', '{"pch": "Depois do fogo\u2026 uma voz mansa e suave. Deus n\u00e3o grita. Ele sussurra. Mas voc\u00ea precisa parar para ouvir.", "verse": "1Rs 19,12", "lectio": "Leia 1Rs 19,9-13. Elias no monte.", "practice": "Liste tudo que est\u00e1 na sua cabe\u00e7a agora. Tudo. Sem filtro.", "question": "Que ru\u00eddo constante ocupa sua mente?"}'),
('61ed9a2c-de4a-446e-bda9-c8902adbe470', 'c3c3c3c3-3030-4000-8000-000000000003', 2, 'Dia 2 — Overload', 'Semana 1: Parar', '{"pch": "Acalmei e sosseguei a minha alma\u2026 como uma crian\u00e7a no colo da m\u00e3e. Menos \u00e9 mais.", "verse": "Sl 131,1-2", "lectio": "Leia Sl 131. O salmo mais curto e mais profundo.", "practice": "Elimine 1 compromisso desnecess\u00e1rio esta semana.", "question": "O que te sobrecarrega mais: o que acontece ou o que voc\u00ea pensa sobre o que acontece?"}'),
('512f28b3-a771-4f78-8330-a88f58f6d656', 'c3c3c3c3-3030-4000-8000-000000000003', 3, 'Dia 3 — Ansiedade', 'Semana 1: Parar', '{"pch": "Basta a cada dia o seu pr\u00f3prio mal\u2026 Pensar no amanh\u00e3 \u00e9 roubar a paz de hoje.", "verse": "Mt 6,34", "lectio": "Leia Mt 6,25-34. Olhai os l\u00edrios do campo.", "practice": "Anote 3 preocupa\u00e7\u00f5es. Ao lado de cada uma, escreva: posso controlar isso? Sim ou n\u00e3o.", "question": "Sobre o que voc\u00ea se preocupa que n\u00e3o pode controlar?"}'),
('a7f8dab1-f5f2-4cd5-aed2-6bd4d8588f66', 'c3c3c3c3-3030-4000-8000-000000000003', 4, 'Dia 4 — Respirar', 'Semana 1: Parar', '{"pch": "Soprou nas suas narinas o f\u00f4lego de vida\u2026 A respira\u00e7\u00e3o \u00e9 o primeiro presente de Deus.", "verse": "Gn 2,7", "lectio": "Leia Gn 2,4-7. Deus formou e soprou.", "practice": "Pratique 5 minutos de respira\u00e7\u00e3o consciente: 4s inspira, 7s segura, 8s expira.", "question": "Quando foi a \u00faltima vez que voc\u00ea respirou com consci\u00eancia?"}'),
('2988c988-44af-4744-bbf5-031bcccf7926', 'c3c3c3c3-3030-4000-8000-000000000003', 5, 'Dia 5 — Pensamentos', 'Semana 1: Parar', '{"pch": "Pensai em tudo o que \u00e9 verdadeiro, nobre, justo\u2026 Voc\u00ea \u00e9 o que pensa repetidamente.", "verse": "Fl 4,8", "lectio": "Leia Fl 4,4-9. A receita da paz.", "practice": "Observe seus pensamentos por 10 min sem reagir. Apenas note.", "question": "Quais pensamentos se repetem na sua mente?"}'),
('b4a145ff-c7e3-4083-bb66-921abf7f0735', 'c3c3c3c3-3030-4000-8000-000000000003', 6, 'Dia 6 — Digital', 'Semana 1: Parar', '{"pch": "O olho n\u00e3o se farta de ver\u2026 nem o ouvido de ouvir. O scroll infinito \u00e9 a torre de Babel moderna.", "verse": "Ec 1,8", "lectio": "Leia Ec 1,1-11. Vaidade das vaidades.", "practice": "Fique 2 horas sem celular. Observe o que acontece dentro de voc\u00ea.", "question": "Quanto tempo por dia sua mente \u00e9 alimentada por telas?"}'),
('cc39322a-514a-4e0e-bc2d-ce1ab1c1eb2d', 'c3c3c3c3-3030-4000-8000-000000000003', 7, 'Dia 7 — Sabbath mental', 'Semana 1: Parar', '{"pch": "Lembra-te do dia de s\u00e1bado para o santificar\u2026 Sua mente tamb\u00e9m precisa de descanso sagrado.", "verse": "Ex 20,8", "lectio": "Leia Ex 20,8-11. O mandamento do descanso.", "practice": "Crie um mini-sabbath: 3 horas sem produtividade, s\u00f3 presen\u00e7a.", "question": "Quando foi a \u00faltima vez que sua mente descansou de verdade?"}'),
('df69c5d1-aa43-4247-a7b5-9ecfd1c5a72b', 'c3c3c3c3-3030-4000-8000-000000000003', 8, 'Dia 8 — Prioridades', 'Semana 2: Organizar', '{"pch": "Maria escolheu a melhor parte\u2026 Nem tudo que \u00e9 urgente \u00e9 importante.", "verse": "Lc 10,42", "lectio": "Leia Lc 10,38-42. Marta e Maria.", "practice": "Liste suas 5 prioridades. Compare com como gasta seu tempo.", "question": "O que \u00e9 realmente importante na sua vida agora?"}'),
('004afa2a-d390-4faa-bbbb-770dff01f616', 'c3c3c3c3-3030-4000-8000-000000000003', 9, 'Dia 9 — Simplicidade', 'Semana 2: Organizar', '{"pch": "Se n\u00e3o vos converterdes como crian\u00e7as\u2026 A crian\u00e7a n\u00e3o complica. Ela vive.", "verse": "Mt 18,3", "lectio": "Leia Mt 18,1-5. Tornar-se como crian\u00e7a.", "practice": "Simplifique 1 \u00e1rea da sua vida hoje. Menos \u00e9 clareza.", "question": "O que voc\u00ea est\u00e1 complicando desnecessariamente?"}'),
('6e35250f-3494-46c4-8a9e-16fd80ebbf64', 'c3c3c3c3-3030-4000-8000-000000000003', 10, 'Dia 10 — Foco', 'Semana 2: Organizar', '{"pch": "Olhando para Jesus\u2026 autor e consumador da f\u00e9. Foco \u00e9 decidir para onde olhar.", "verse": "Hb 12,2", "lectio": "Leia Hb 12,1-3. Correr com perseveran\u00e7a.", "practice": "Escolha 1 coisa importante. Dedique 1 hora ininterrupta a ela.", "question": "No que voc\u00ea deveria estar focado mas n\u00e3o est\u00e1?"}'),
('6de31ec2-ad63-42ce-8a40-c843f91b4eaa', 'c3c3c3c3-3030-4000-8000-000000000003', 11, 'Dia 11 — Decisões', 'Semana 2: Organizar', '{"pch": "Se algu\u00e9m tem falta de sabedoria, pe\u00e7a a Deus\u2026 Clareza vem de quem v\u00ea tudo.", "verse": "Tg 1,5", "lectio": "Leia Tg 1,2-8. Pedir com f\u00e9, sem duvidar.", "practice": "Ore especificamente sobre uma decis\u00e3o. Depois, escreva o que sentiu.", "question": "Que decis\u00e3o te paralisa por falta de clareza?"}'),
('09fbf4de-26cd-4257-ad1f-04d5c75458f6', 'c3c3c3c3-3030-4000-8000-000000000003', 12, 'Dia 12 — Mente renovada', 'Semana 2: Organizar', '{"pch": "Transformai-vos pela renova\u00e7\u00e3o da mente\u2026 Pensar diferente \u00e9 o come\u00e7o de viver diferente.", "verse": "Rm 12,2", "lectio": "Leia Rm 12,1-2. Culto racional.", "practice": "Identifique 1 pensamento negativo recorrente. Substitua por uma verdade b\u00edblica.", "question": "Que padr\u00e3o de pensamento precisa mudar?"}'),
('f27b563c-6f42-42ae-9c21-029b44359198', 'c3c3c3c3-3030-4000-8000-000000000003', 13, 'Dia 13 — Verdade', 'Semana 2: Organizar', '{"pch": "Conhecereis a verdade e a verdade vos libertar\u00e1\u2026 Mentiras internas aprisionam. A verdade liberta.", "verse": "Jo 8,32", "lectio": "Leia Jo 8,31-36. A liberdade real.", "practice": "Escreva a mentira. Ao lado, escreva a verdade de Deus sobre voc\u00ea.", "question": "Que mentira sobre si mesmo voc\u00ea acreditou por tempo demais?"}'),
('576dc901-367c-491c-88a5-7633757d1521', 'c3c3c3c3-3030-4000-8000-000000000003', 14, 'Dia 14 — Silêncio', 'Semana 2: Organizar', '{"pch": "Aquietai-vos\u2026 No sil\u00eancio, os pensamentos se acomodam como sedimento na \u00e1gua.", "verse": "Sl 46,10", "lectio": "Leia Sl 46. Deus \u00e9 ref\u00fagio.", "practice": "15 minutos de sil\u00eancio contemplativo. Sem guia, sem m\u00fasica.", "question": "O que aparece quando tudo fica em sil\u00eancio?"}'),
('51f9a773-6c24-4386-adc1-05b27c4bc477', 'c3c3c3c3-3030-4000-8000-000000000003', 15, 'Dia 15 — Sabedoria', 'Semana 3: Discernir', '{"pch": "O princ\u00edpio da sabedoria \u00e9: adquire sabedoria\u2026 A sabedoria n\u00e3o \u00e9 informa\u00e7\u00e3o \u2014 \u00e9 discernimento.", "verse": "Pv 4,7", "lectio": "Leia Pv 4,1-9. A sabedoria como tesouro.", "practice": "Pe\u00e7a conselho a algu\u00e9m mais velho e s\u00e1bio sobre algo que te inquieta.", "question": "Qual a diferen\u00e7a entre saber e ser s\u00e1bio na sua vida?"}'),
('183e992f-ce19-4f65-980d-897b462aa522', 'c3c3c3c3-3030-4000-8000-000000000003', 16, 'Dia 16 — Discernimento', 'Semana 3: Discernir', '{"pch": "Provai os esp\u00edritos\u2026 Nem todo pensamento que surge \u00e9 verdadeiro. Discernir \u00e9 separar.", "verse": "1Jo 4,1", "lectio": "Leia 1Jo 4,1-6. O esp\u00edrito da verdade.", "practice": "Hoje, antes de agir por impulso, pergunte: isso vem da paz ou da ansiedade?", "question": "Como voc\u00ea distingue um pensamento \u00fatil de um destrutivo?"}'),
('39521ae4-ffb9-43ae-b257-192f8330ce80', 'c3c3c3c3-3030-4000-8000-000000000003', 17, 'Dia 17 — Intuição', 'Semana 3: Discernir', '{"pch": "O Esp\u00edrito da verdade vos guiar\u00e1\u2026 Intui\u00e7\u00e3o espiritual \u00e9 o GPS divino.", "verse": "Jo 16,13", "lectio": "Leia Jo 16,12-15. O Esp\u00edrito ensina.", "practice": "Tome uma decis\u00e3o pequena hoje usando apenas intui\u00e7\u00e3o e ora\u00e7\u00e3o.", "question": "Quando sua intui\u00e7\u00e3o te guiou corretamente?"}'),
('3c5ad66f-3af6-43a7-a225-7aa6f232da86', 'c3c3c3c3-3030-4000-8000-000000000003', 18, 'Dia 18 — Paciência', 'Semana 3: Discernir', '{"pch": "A perseveran\u00e7a tenha obra perfeita\u2026 Clareza raramente \u00e9 instant\u00e2nea. \u00c0s vezes, esperar \u00e9 a resposta.", "verse": "Tg 1,4", "lectio": "Leia Tg 1,2-4. Alegria nas prova\u00e7\u00f5es.", "practice": "Espere antes de responder algo hoje. Observe o que muda.", "question": "Em que \u00e1rea da vida voc\u00ea precisa de mais paci\u00eancia?"}'),
('58587bc7-c34a-4cff-834a-6abdb165c3ad', 'c3c3c3c3-3030-4000-8000-000000000003', 19, 'Dia 19 — Perspectiva', 'Semana 3: Discernir', '{"pch": "Os meus pensamentos n\u00e3o s\u00e3o os vossos pensamentos\u2026 \u00c0s vezes, clareza \u00e9 aceitar que voc\u00ea n\u00e3o v\u00ea tudo.", "verse": "Is 55,8-9", "lectio": "Leia Is 55,6-11. A palavra que n\u00e3o volta vazia.", "practice": "Escreva sua situa\u00e7\u00e3o atual como se fosse Deus descrevendo-a para voc\u00ea.", "question": "O que mudaria se voc\u00ea visse sua situa\u00e7\u00e3o do ponto de vista de Deus?"}'),
('7dc18a7c-f96b-41c1-8ac6-60b3db7444e4', 'c3c3c3c3-3030-4000-8000-000000000003', 20, 'Dia 20 — Soltar', 'Semana 3: Discernir', '{"pch": "Lan\u00e7a sobre o Senhor o teu fardo\u2026 Pensamentos obsessivos s\u00e3o fardos que n\u00e3o te pertencem.", "verse": "Sl 55,22", "lectio": "Leia Sl 55,16-23. Deus sustenta.", "practice": "Escreva o pensamento que te atormenta num papel. Depois, rasgue-o como ato simb\u00f3lico.", "question": "Que pensamento voc\u00ea precisa parar de carregar?"}'),
('a80a6282-9cba-41df-99a0-7c50d3cc0798', 'c3c3c3c3-3030-4000-8000-000000000003', 21, 'Dia 21 — Ordem interior', 'Semana 3: Discernir', '{"pch": "Deus n\u00e3o \u00e9 de confus\u00e3o, mas de paz\u2026 A ordem interior reflete a ordem divina.", "verse": "1Cor 14,33", "lectio": "Leia 1Cor 14,26-33. Ordem no culto.", "practice": "Organize algo externo (mesa, quarto, agenda) como reflexo da ordem interna que busca.", "question": "O que na sua vida interna est\u00e1 bagun\u00e7ado?"}'),
('68bfdebc-e08e-4eca-b3a9-27d1160b6c90', 'c3c3c3c3-3030-4000-8000-000000000003', 22, 'Dia 22 — Atenção', 'Semana 4: Integrar', '{"pch": "Cuidado com o modo como voc\u00eas ouvem\u2026 Aten\u00e7\u00e3o \u00e9 a ora\u00e7\u00e3o mais b\u00e1sica.", "verse": "Lc 8,18", "lectio": "Leia Lc 8,16-18. A l\u00e2mpada e a aten\u00e7\u00e3o.", "practice": "Pratique aten\u00e7\u00e3o plena numa atividade simples: comer, caminhar, respirar.", "question": "No que voc\u00ea tem prestado aten\u00e7\u00e3o?"}'),
('ffed5b73-6714-4a5d-bcfd-649a6ad5a7dc', 'c3c3c3c3-3030-4000-8000-000000000003', 23, 'Dia 23 — Rotina', 'Semana 4: Integrar', '{"pch": "Daniel orava tr\u00eas vezes ao dia\u2026 Rotina sagrada cria espa\u00e7o para clareza.", "verse": "Dn 6,10", "lectio": "Leia Dn 6,6-13. A fidelidade de Daniel.", "practice": "Crie uma rotina matinal de 15 min: sil\u00eancio, leitura, ora\u00e7\u00e3o.", "question": "Como \u00e9 sua rotina matinal? Ela alimenta ou drena sua mente?"}'),
('f4e9174e-8067-45cb-97bd-56e0628f5b55', 'c3c3c3c3-3030-4000-8000-000000000003', 24, 'Dia 24 — Contentamento', 'Semana 4: Integrar', '{"pch": "Aprendi a estar contente em toda situa\u00e7\u00e3o\u2026 Contentamento n\u00e3o \u00e9 conformismo \u2014 \u00e9 liberdade.", "verse": "Fl 4,11", "lectio": "Leia Fl 4,10-13. O segredo de Paulo.", "practice": "Liste 10 coisas que j\u00e1 tem e que algu\u00e9m sonha em ter.", "question": "O que te falta para ser feliz? Ser\u00e1 que realmente falta?"}'),
('bcc2b146-9844-4222-b920-924ad03d7c3b', 'c3c3c3c3-3030-4000-8000-000000000003', 25, 'Dia 25 — Criatividade', 'Semana 4: Integrar', '{"pch": "No princ\u00edpio, Deus criou\u2026 Criatividade \u00e9 imagem de Deus em a\u00e7\u00e3o. Mentes claras criam.", "verse": "Gn 1,1", "lectio": "Leia Gn 1,1-5. O primeiro ato criativo.", "practice": "Crie algo hoje: um texto, um desenho, uma m\u00fasica, uma receita.", "question": "O que voc\u00ea criaria se tivesse clareza?"}'),
('41a9b8e8-9f49-47c6-a8b8-bd1084b4a01e', 'c3c3c3c3-3030-4000-8000-000000000003', 26, 'Dia 26 — Palavras', 'Semana 4: Integrar', '{"pch": "A morte e a vida est\u00e3o no poder da l\u00edngua\u2026 O que voc\u00ea diz molda o que voc\u00ea pensa.", "verse": "Pv 18,21", "lectio": "Leia Pv 18,20-21. O fruto da boca.", "practice": "Hoje, fale apenas o que edifica. Observe como isso muda seu estado mental.", "question": "Que palavras voc\u00ea repete sobre si mesmo?"}'),
('b90cea0d-39c9-41de-a0d0-39a1b35457af', 'c3c3c3c3-3030-4000-8000-000000000003', 27, 'Dia 27 — Direção', 'Semana 4: Integrar', '{"pch": "L\u00e2mpada para os meus p\u00e9s\u2026 A Palavra n\u00e3o ilumina o caminho todo \u2014 s\u00f3 o pr\u00f3ximo passo.", "verse": "Sl 119,105", "lectio": "Leia Sl 119,105-112. Luz suficiente.", "practice": "Defina 1 pr\u00f3ximo passo claro. N\u00e3o o segundo. S\u00f3 o primeiro.", "question": "Qual \u00e9 o pr\u00f3ximo passo que voc\u00ea precisa dar?"}'),
('7fded1c2-46aa-483e-a0c5-3b254ebf399f', 'c3c3c3c3-3030-4000-8000-000000000003', 28, 'Dia 28 — Confiança', 'Semana 4: Integrar', '{"pch": "Confia no Senhor\u2026 e n\u00e3o te estribes no teu pr\u00f3prio entendimento. Clareza final vem da rendi\u00e7\u00e3o.", "verse": "Pv 3,5-6", "lectio": "Leia Pv 3,1-8. O caminho da confian\u00e7a.", "practice": "Entregue uma decis\u00e3o a Deus hoje. Confie sem entender.", "question": "Em que \u00e1rea voc\u00ea tenta entender quando deveria confiar?"}'),
('6ac00f54-adf7-4709-8814-c82ec54c3c00', 'c3c3c3c3-3030-4000-8000-000000000003', 29, 'Dia 29 — Paz mental', 'Semana 4: Integrar', '{"pch": "A paz de Deus que excede todo entendimento\u2026 guardar\u00e1 vosso cora\u00e7\u00e3o e mente. Paz que a l\u00f3gica n\u00e3o explica.", "verse": "Fl 4,7", "lectio": "Leia Fl 4,6-7. Ora\u00e7\u00e3o que gera paz.", "practice": "Ore sobre cada preocupa\u00e7\u00e3o. Depois, agrade\u00e7a como se j\u00e1 tivesse a resposta.", "question": "O que significaria ter paz mental de verdade?"}'),
('245fdff3-766d-4c27-b4d3-acdfbf435181', 'c3c3c3c3-3030-4000-8000-000000000003', 30, 'Dia 30 — Mente clara', 'Semana 4: Integrar', '{"pch": "Deus nos deu esp\u00edrito de poder, amor e mente s\u00e3\u2026 Clareza mental n\u00e3o \u00e9 destino \u2014 \u00e9 pr\u00e1tica di\u00e1ria.", "verse": "2Tm 1,7", "lectio": "Leia 2Tm 1,6-12. Reavivar a chama.", "practice": "Releia todas as reflex\u00f5es. Escreva seu manifesto de clareza mental em 5 frases.", "question": "O que mudou na sua mente nesses 30 dias?"}'),
('6248ed3e-911f-46ee-ad1f-d94b08f19285', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 1, 'O olhar que se volta', NULL, '{"intro": "Psicologicamente, aceitar a exist\u00eancia de uma dor \u00e9 o in\u00edcio do fim do trauma.", "prayer": "Escreva sobre essa ferida sem filtros.", "practice": "Reserve 5 minutos para olhar honestamente para algo que lhe d\u00f3i.", "reflection": "A ferida s\u00f3 pode ser curada quando deixamos de escond\u00ea-la de n\u00f3s mesmos. O primeiro passo \u00e9 o reconhecimento.", "journal_prompt": "O que em voc\u00ea ainda tem medo de ser visto?"}'),
('7f70a32a-9138-415d-bd27-f56ce3062fe6', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 2, 'O perdão como libertação', NULL, '{"intro": "O ressentimento \u00e9 uma pris\u00e3o que voc\u00ea constr\u00f3i para o outro e acaba morando nela.", "prayer": "Em sil\u00eancio, pronuncie: Eu o libero, eu me libero.", "practice": "Identifique uma pessoa ou situa\u00e7\u00e3o que voc\u00ea ainda carrega.", "reflection": "Perdoar n\u00e3o \u00e9 esquecer, \u00e9 tirar o peso do passado dos seus ombros.", "journal_prompt": "Qual peso voc\u00ea est\u00e1 pronto para soltar?"}'),
('77eaa697-dc89-43bd-ab9f-361cc131577b', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 3, 'A voz que consola', NULL, '{"intro": "O trauma nos isola; a cura nos reconecta \u00e0 nossa pr\u00f3pria dignidade.", "prayer": "Fique em sil\u00eancio absoluto por 10 minutos.", "practice": "Respire fundo e imagine-se sendo abra\u00e7ado pelo amor que nunca falha.", "reflection": "A cura vem de uma voz que sussurra: voc\u00ea n\u00e3o est\u00e1 mais sozinho.", "journal_prompt": "Se o amor falasse com voc\u00ea hoje, o que diria?"}'),
('c4566c85-797e-499d-ae19-11db3cea8862', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 4, 'Desapego do passado', NULL, '{"intro": "Tentar viver no passado \u00e9 tentar preencher um vaso quebrado com areia.", "prayer": "Queime esse papel simbolicamente ou rasgue-o.", "practice": "Liste tr\u00eas coisas que te mant\u00eam preso ao que j\u00e1 passou.", "reflection": "O passado \u00e9 um espelho, n\u00e3o uma morada.", "journal_prompt": "Quem voc\u00ea seria se n\u00e3o carregasse esse passado?"}'),
('bb55db15-57da-46f0-bb9f-f8ae171b0372', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 5, 'A nova identidade', NULL, '{"intro": "A cura redefine sua narrativa pessoal.", "prayer": "Afirme essas qualidades em voz alta.", "practice": "Defina-se agora com tr\u00eas qualidades que n\u00e3o dependem da sua dor.", "reflection": "Voc\u00ea n\u00e3o \u00e9 o que te aconteceu, voc\u00ea \u00e9 o que voc\u00ea escolhe fazer com isso.", "journal_prompt": "Como \u00e9 a sua vida quando voc\u00ea aceita quem voc\u00ea realmente \u00e9?"}'),
('bdf97817-250e-4e91-b8a6-0817621003d6', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 6, 'A paciência com o processo', NULL, '{"intro": "A impaci\u00eancia \u00e9 a voz da pressa, e a cura exige tempo.", "prayer": "Respire profundamente 5 vezes, aceitando o seu tempo.", "practice": "Observe o seu ritmo hoje, sem querer for\u00e7ar nada.", "reflection": "A cura \u00e9 uma espiral, n\u00e3o uma linha reta.", "journal_prompt": "Por que voc\u00ea tem tanta pressa em ser perfeito?"}'),
('71feb284-a2c1-4cb8-a060-d7aba375b100', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 7, 'O início da vida', NULL, '{"intro": "Agora que a ferida n\u00e3o te define, a vida pode florescer.", "prayer": "Agrade\u00e7a pela sua pr\u00f3pria exist\u00eancia.", "practice": "Planeje um pequeno gesto de cuidado com voc\u00ea mesmo.", "reflection": "Curar \u00e9, finalmente, come\u00e7ar a viver.", "journal_prompt": "Qual \u00e9 o primeiro passo da sua vida renovada?"}')
